    /// groups.create (contract revision 1.126, §4.107, capability
    /// group-management): the local shape ladder, then the upstream frame.
    /// The official createGroupV2 posture — the engine derives the new group
    /// master key and answers {groupId, revision}. The title gate mirrors
    /// the engine's shape face (required non-empty, the §4.104 256-byte
    /// `groupName` bound); the optional roster carries the §4.44 bounds
    /// when present (an explicit empty array is the engine's own refusal —
    /// the local ladder mirrors it, absent stays absent); the avatar
    /// data URI is validated locally (the §4.45 setProfile gate) so a
    /// malformed URI answers INVALID_REQUEST before any upstream call.
    pub fn prepare_groups_create(
        &self,
        params: &GroupsCreateParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        if params.title.is_empty() || params.title.len() > GROUP_NAME_MAX_BYTES {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "title must contain between 1 and 256 bytes",
                false,
            )));
        }
        if let Some(members) = &params.members
            && (members.is_empty()
                || members.len() > MAX_GROUP_MEMBERS
                || members.iter().any(|member| {
                    member.is_empty() || member.chars().count() > MAX_GROUP_MEMBER_ID_CHARS
                }))
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "members carries at most 1001 entries of 1-128 characters",
                false,
            )));
        }
        let avatar = match &params.avatar {
            AvatarUpdate::Replace(data_uri) => {
                AvatarUpdate::Replace(validate_avatar_data_uri(data_uri)?)
            }
            keep_or_remove => keep_or_remove.clone(),
        };
        let account = self.resolve_account(&params.account_id)?;
        let mut upstream = json!({
            "account": account.signal_account,
            "title": params.title,
        });
        if let Some(expiration) = params.expiration {
            upstream["expiration"] = json!(expiration);
        }
        match avatar {
            AvatarUpdate::Keep => {}
            AvatarUpdate::Remove => {
                upstream["avatar"] = Value::Null;
            }
            AvatarUpdate::Replace(data_uri) => {
                upstream["avatar"] = json!(data_uri);
            }
        }
        if let Some(members) = &params.members {
            upstream["members"] = json!(members);
        }
        Ok(upstream)
    }

    /// groups.migrate (contract revision 1.123, §4.104, capability
    /// group-management): the local shape ladder, then the upstream frame.
    /// The legacy group id is addressed directly — no local conversation row
    /// is resolved (the desktop owns the GV1 roster it hands over; the
    /// migrated group converges through contacts.sync like every group row).
    /// The id gate mirrors the engine's shape face (standard base64, non-empty
    /// — the engine pins no 16-byte length, the HKDF derivation primitive is
    /// defined over arbitrary bytes); the member bounds are the §4.44
    /// discipline verbatim (non-empty, 1-1001 entries of 1-128 characters);
    /// title/expiration carry the optional change set; the avatar data URI is
    /// validated locally (the same `validate_avatar_data_uri` gate the
    /// §4.45 setProfile face runs) so a malformed URI answers
    /// INVALID_REQUEST before any upstream call instead of folding into the
    /// generic upstream family.
    pub fn prepare_groups_migrate(
        &self,
        params: &GroupsMigrateParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        {
            let mut decoded = Vec::new();
            let decoded_ok =
                base64_decode_to_vec(&params.group_id, &mut decoded).is_ok() && !decoded.is_empty();
            if !decoded_ok {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "groupId must be the legacy group id in standard base64",
                    false,
                )));
            }
        }
        if let Some(title) = params.title.as_deref()
            && (title.is_empty() || title.len() > GROUP_NAME_MAX_BYTES)
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "title must contain between 1 and 256 bytes",
                false,
            )));
        }
        if params.members.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "the migration must carry the V1 member roster; an empty array is a shape error",
                false,
            )));
        }
        if params.members.len() > MAX_GROUP_MEMBERS
            || params.members.iter().any(|member| {
                member.is_empty() || member.chars().count() > MAX_GROUP_MEMBER_ID_CHARS
            })
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "members carries at most 1001 entries of 1-128 characters",
                false,
            )));
        }
        let avatar = match &params.avatar {
            AvatarUpdate::Replace(data_uri) => {
                AvatarUpdate::Replace(validate_avatar_data_uri(data_uri)?)
            }
            keep_or_remove => keep_or_remove.clone(),
        };
        let account = self.resolve_account(&params.account_id)?;
        let mut upstream = json!({
            "account": account.signal_account,
            "groupId": params.group_id,
        });
        if let Some(title) = params.title.as_deref() {
            upstream["title"] = json!(title);
        }
        if let Some(expiration) = params.expiration {
            upstream["expiration"] = json!(expiration);
        }
        match avatar {
            AvatarUpdate::Keep => {}
            AvatarUpdate::Remove => {
                upstream["avatar"] = Value::Null;
            }
            AvatarUpdate::Replace(data_uri) => {
                upstream["avatar"] = json!(data_uri);
            }
        }
        upstream["members"] = json!(params.members);
        Ok(upstream)
    }

    /// messages.sendContact (contract revision 1.124, §4.105, capability
    /// send-contact): the local shape ladder, then the upstream frame. The
    /// conversation row's kind decides the leg — a direct row routes the
    /// engine's 1:1 `sendContact` (recipient = the row's peer reference), a
    /// group row the `groupId` group leg (the calls.sendSignal 1:82
    /// addressing precedent: the connector already holds the kind, so no new
    /// parameter). The card gates are fail-closed before any upstream call
    /// (the engine's parse face mirrors them, but a local refusal never
    /// spends a fan-out frame): an all-empty card carries nothing and
    /// answers INVALID_REQUEST; every entry array holds at most 64 entries;
    /// every scalar is bounded at 128 characters with the entry values
    /// non-empty; the `type` vocabularies are the official numberTo*Type
    /// words (number/email: HOME | MOBILE | WORK | CUSTOM, address:
    /// HOME | WORK | CUSTOM — the postal enum never had a MOBILE; the
    /// official client silently folds out-of-vocabulary words to HOME and
    /// the engine refuses instead, the textStyle precedent); the avatar
    /// data URI rides the §4.45 setProfile gate; the organization's empty
    /// string is the official falsy-absent and drops from the upstream
    /// frame.
    pub fn prepare_messages_send_contact(
        &self,
        params: &MessagesSendContactParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        if params.conversation_id.is_empty()
            || params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        validate_contact_payload(&params.contact)?;
        let account = self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        let mut upstream = if conversation.kind == "group" {
            json!({
                "account": account.signal_account,
                "groupId": conversation.peer_key,
            })
        } else if conversation.kind == "direct" {
            json!({
                "account": account.signal_account,
                "recipient": conversation.peer_key,
            })
        } else {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "messages.sendContact addresses direct or group conversations only",
                false,
            )));
        };
        let mut contact = params.contact.clone();
        if contact.organization.as_deref() == Some("") {
            contact.organization = None;
        }
        upstream["contact"] = serde_json::to_value(&contact).unwrap_or(Value::Null);
        Ok(upstream)
    }

    /// The §4.106 poll legs are group-only (the official desktop ships polls
    /// in group conversations exclusively — the 1:1 create form rides a
    /// feature flag that defaults off, vote/terminate have no 1:1 form at
    /// all): resolve the rows and refuse any non-group conversation before
    /// any upstream call.
    fn resolve_poll_group_leg(
        &self,
        account_id: &str,
        conversation_id: &str,
    ) -> Result<(AccountRow, crate::store::ConversationRow), ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        if conversation_id.is_empty()
            || conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_conversation(account_id, conversation_id)?;
        if conversation.kind != "group" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "polls are group-conversation faces; the official desktop ships them in groups exclusively",
                false,
            )));
        }
        Ok((account, conversation))
    }

    /// messages.sendPollCreate (contract revision 1.125, §4.106, capability
    /// polls): the content gates (the official PollCreateSchema face
    /// verbatim — question 1..=200 characters within 2048 bytes, options
    /// 2..=10 entries of 1..=100 characters within 2048 bytes), then the
    /// engine's group-only `sendPollCreate` frame; allowMultiple rides when
    /// present (absent stays absent — the engine's false default).
    pub fn prepare_messages_send_poll_create(
        &self,
        params: &MessagesSendPollCreateParams,
    ) -> Result<Value, ServiceError> {
        let (account, conversation) =
            self.resolve_poll_group_leg(&params.account_id, &params.conversation_id)?;
        validate_poll_question(&params.question)?;
        validate_poll_options(&params.options)?;
        let mut upstream = json!({
            "account": account.signal_account,
            "groupId": conversation.peer_key,
            "question": params.question,
            "options": params.options,
        });
        if let Some(allow_multiple) = params.allow_multiple {
            upstream["allowMultiple"] = json!(allow_multiple);
        }
        Ok(upstream)
    }

    /// messages.sendPollVote (contract revision 1.125, §4.106): the anchor
    /// gates (targetAuthor the §4.44 member-id bound; targetTimestamp a
    /// positive integer — the official `z.number().int().positive()`), the
    /// selection gate (optionIndexes 0..=9, at most 10 entries, empty =
    /// the legal clear-vote; voteCount positive, absent = the engine's 1
    /// default), then the engine's group-only `sendPollVote` frame.
    pub fn prepare_messages_send_poll_vote(
        &self,
        params: &MessagesSendPollVoteParams,
    ) -> Result<Value, ServiceError> {
        let (account, conversation) =
            self.resolve_poll_group_leg(&params.account_id, &params.conversation_id)?;
        if params.target_author.is_empty()
            || params.target_author.chars().count() > MAX_POLL_TARGET_AUTHOR_CHARS
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "targetAuthor must contain between 1 and 128 characters",
                false,
            )));
        }
        if params.target_timestamp == 0 {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "targetTimestamp must be a positive integer",
                false,
            )));
        }
        validate_poll_option_indexes(&params.option_indexes)?;
        if let Some(count) = params.vote_count
            && count == 0
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "voteCount must be a positive integer",
                false,
            )));
        }
        let mut upstream = json!({
            "account": account.signal_account,
            "groupId": conversation.peer_key,
            "targetAuthor": params.target_author,
            "targetTimestamp": params.target_timestamp,
            "optionIndexes": params.option_indexes,
        });
        if let Some(count) = params.vote_count {
            upstream["voteCount"] = json!(count);
        }
        Ok(upstream)
    }

    /// messages.sendPollTerminate (contract revision 1.125, §4.106): the
    /// anchor gate (targetTimestamp positive), then the engine's group-only
    /// `sendPollTerminate` frame.
    pub fn prepare_messages_send_poll_terminate(
        &self,
        params: &MessagesSendPollTerminateParams,
    ) -> Result<Value, ServiceError> {
        let (account, conversation) =
            self.resolve_poll_group_leg(&params.account_id, &params.conversation_id)?;
        if params.target_timestamp == 0 {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "targetTimestamp must be a positive integer",
                false,
            )));
        }
        Ok(json!({
            "account": account.signal_account,
            "groupId": conversation.peer_key,
            "targetTimestamp": params.target_timestamp,
        }))
    }

    /// messages.reportSpam (contract revision 1.49, §4.48, capability
    /// report-spam): resolve the direct conversation's rows to the engine's
    /// `reportSpam {account, targetAci, serverGuids}` payload. The report is
    /// an upstream protocol action — zero local writes; rows that never
    /// carried a serverGuid (sent rows, history imports) cannot be reported
    /// and land in the caller's per-id failures instead. A group
    /// conversation is refused before any upstream call, and a numeric peer
    /// without a recorded ACI mapping is a deterministic refusal — the
    /// report would mis-address upstream.
    pub fn prepare_report_spam(
        &self,
        params: &MessagesReportSpamParams,
    ) -> Result<PreparedReportSpam, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        validate_opaque_id(&params.conversation_id, "conversationId")?;
        if params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if params.message_ids.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "messageIds must carry at least one id",
                false,
            )));
        }
        if params.message_ids.len() > REPORT_SPAM_MESSAGE_IDS_LIMIT
            || params
                .message_ids
                .iter()
                .any(|id| id.is_empty() || id.chars().count() > MAX_OPAQUE_ID_BYTES)
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "messageIds must carry at most 64 entries of 1-128 characters",
                false,
            )));
        }
        let account = self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        if conversation.kind != "direct" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "messages.reportSpam addresses a direct conversation",
                false,
            )));
        }
        let target_aci = self.report_target_aci(&account.id, &conversation.peer_key)?;
        let guids =
            self.store
                .server_guids_by_ids(&account.id, &conversation.id, &params.message_ids)?;
        let mut upstream = json!({
            "account": account.signal_account,
            "targetAci": target_aci,
        });
        let pairs = params
            .message_ids
            .iter()
            .zip(guids)
            .filter_map(|(message_id, server_guid)| {
                server_guid.map(|guid| (message_id.clone(), guid))
            })
            .collect::<Vec<_>>();
        upstream["serverGuids"] = json!(pairs.iter().map(|(_, guid)| guid).collect::<Vec<_>>());
        Ok(PreparedReportSpam { upstream, pairs })
    }

    /// The report address (contract revision 1.49, §4.48): a UUID-shaped
    /// peer key is the ACI itself; otherwise the ingest-recorded
    /// ACI↔peer-key mapping answers. A numeric peer with no recorded
    /// mapping never falls back to the number — the upstream targetAci
    /// parses only ServiceIds, and guessing would mis-address the report.
    fn report_target_aci(&self, account_id: &str, peer_key: &str) -> Result<String, ServiceError> {
        if is_uuid_shaped(peer_key) {
            return Ok(peer_key.to_string());
        }
        self.store
            .aci_for_peer_key(account_id, peer_key)?
            .ok_or_else(|| {
                ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "report target ACI is not resolvable for this conversation",
                    false,
                ))
            })
    }

