    /// storage.mergeContacts / storage.importGroups / storage.getCallLinks
    /// (contract revision 1.131, §4.112): the single-parameter ladder —
    /// account bounds and resolution, the service reads nothing locally.
    /// mergeContacts/importGroups are engine-local ingest reads (the
    /// engine's own Storage Service contact/group merge); getCallLinks is
    /// the cloud call-link read. The record grammars stay the engine's.
    pub fn prepare_storage_ingest_read(&self, account_id: &str) -> Result<Value, ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        let account = self.resolve_account(account_id)?;
        Ok(json!({ "account": account.signal_account }))
    }

    /// storage.setCallLink (contract revision 1.131, §4.112): the local
    /// intent gates before any upstream call — the rootKey identity face
    /// (non-empty, bounded 128 characters; the 32-byte base64 grammar stays
    /// the engine's), the optional arms shape-gated (adminPasskey string,
    /// deletedAtTimestampMs a positive integer — 0 is the engine's own
    /// no-action refusal mirrored), and the exactly-one intent rule (both
    /// arms present is the official same-position contradiction, neither is
    /// the empty intent the official upload never writes). The frame
    /// carries only the provided arms; null folds to absent (the engine
    /// reads both the same way).
    pub fn prepare_storage_set_call_link(
        &self,
        params: &StorageSetCallLinkParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        if params.root_key.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "rootKey is required",
                false,
            )));
        }
        if params.root_key.chars().count() > MAX_CALL_LINK_KEY_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "rootKey exceeds 128 characters",
                false,
            )));
        }
        if let Some(passkey) = params.admin_passkey.as_deref()
            && (passkey.is_empty() || passkey.chars().count() > MAX_CALL_LINK_KEY_CHARS)
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "adminPasskey must be a non-empty string of at most 128 characters",
                false,
            )));
        }
        if params.deleted_at_timestamp_ms == Some(0) {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "deletedAtTimestampMs must be a positive integer (0 carries no delete intent)",
                false,
            )));
        }
        if params.admin_passkey.is_some() && params.deleted_at_timestamp_ms.is_some() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "adminPasskey and deletedAtTimestampMs are contradictory intents; send exactly one",
                false,
            )));
        }
        if params.admin_passkey.is_none() && params.deleted_at_timestamp_ms.is_none() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "one of adminPasskey, deletedAtTimestampMs is required",
                false,
            )));
        }
        let account = self.resolve_account(&params.account_id)?;
        let mut upstream = serde_json::Map::new();
        upstream.insert(
            "account".into(),
            Value::String(account.signal_account.clone()),
        );
        upstream.insert("rootKey".into(), Value::String(params.root_key.clone()));
        if let Some(passkey) = params.admin_passkey.as_deref() {
            upstream.insert("adminPasskey".into(), Value::String(passkey.to_string()));
        }
        if let Some(stamp) = params.deleted_at_timestamp_ms {
            upstream.insert("deletedAtTimestampMs".into(), json!(stamp));
        }
        Ok(Value::Object(upstream))
    }

    /// accounts.updateConfiguration (contract revision 1.46, §4.45; the
    /// 1.120 §4.101 linkPreviews bit): at-least-one-writable-key fail-closed,
    /// the sharing-mode enum, and account resolution under the service lock;
    /// only the provided keys are forwarded so the upstream partial-write
    /// semantics (official updateConfiguration: write exactly the provided
    /// fields, read the rest back untouched) survive the hop. No local row is
    /// written.
    pub fn prepare_accounts_update_configuration(
        &self,
        params: &AccountsUpdateConfigurationParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        let provided = [
            params.read_receipts.is_some(),
            params.typing_indicators.is_some(),
            params.phone_number_sharing_mode.is_some(),
            params.unlisted_phone_number.is_some(),
            params.link_previews.is_some(),
        ];
        if !provided.iter().any(|present| *present) {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "at least one of readReceipts, typingIndicators, phoneNumberSharingMode, unlistedPhoneNumber, linkPreviews is required",
                false,
            )));
        }
        if let Some(mode) = params.phone_number_sharing_mode.as_deref()
            && !matches!(mode, "everybody" | "nobody")
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "phoneNumberSharingMode must be 'everybody' or 'nobody'",
                false,
            )));
        }
        let account = self.resolve_account(&params.account_id)?;
        let mut upstream = json!({ "account": account.signal_account });
        if let Some(read_receipts) = params.read_receipts {
            upstream["readReceipts"] = json!(read_receipts);
        }
        if let Some(typing_indicators) = params.typing_indicators {
            upstream["typingIndicators"] = json!(typing_indicators);
        }
        if let Some(mode) = params.phone_number_sharing_mode.as_deref() {
            upstream["phoneNumberSharingMode"] = json!(mode);
        }
        if let Some(unlisted_phone_number) = params.unlisted_phone_number {
            upstream["unlistedPhoneNumber"] = json!(unlisted_phone_number);
        }
        if let Some(link_previews) = params.link_previews {
            upstream["linkPreviews"] = json!(link_previews);
        }
        Ok(upstream)
    }

    /// accounts.setProfile (contract revision 1.46, §4.45): the text-face
    /// bounds (official desktop ProfileEditor budgets, §4.45) and the avatar
    /// tri-state resolve under the service lock; the optional text keys pass
    /// through as-is because the upstream text face is a full write — a key
    /// the caller omits is cleared upstream, exactly the official
    /// updateProfile semantics. No local row is written.
    pub fn prepare_accounts_set_profile(
        &self,
        params: &AccountsSetProfileParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        if params.given_name.is_empty() || params.given_name.len() > MAX_PROFILE_NAME_BYTES {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "givenName must contain between 1 and 128 bytes",
                false,
            )));
        }
        if let Some(family_name) = params.family_name.as_deref()
            && family_name.len() > MAX_PROFILE_NAME_BYTES
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "familyName must contain at most 128 bytes",
                false,
            )));
        }
        if let Some(about) = params.about.as_deref()
            && about.len() > MAX_PROFILE_ABOUT_BYTES
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "about must contain at most 512 bytes",
                false,
            )));
        }
        if let Some(emoji) = params.emoji.as_deref()
            && emoji.len() > MAX_EMOJI_BYTES
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "emoji must contain at most 32 bytes",
                false,
            )));
        }
        let avatar = match &params.avatar {
            AvatarUpdate::Replace(data_uri) => {
                AvatarUpdate::Replace(validate_avatar_data_uri(data_uri)?)
            }
            keep_or_remove => keep_or_remove.clone(),
        };
        let account = self.resolve_account(&params.account_id)?;
        let mut upstream = json!({
            "account": account.signal_account,
            "givenName": params.given_name,
        });
        if let Some(family_name) = params.family_name.as_deref() {
            upstream["familyName"] = json!(family_name);
        }
        if let Some(about) = params.about.as_deref() {
            upstream["about"] = json!(about);
        }
        if let Some(emoji) = params.emoji.as_deref() {
            upstream["emoji"] = json!(emoji);
        }
        match avatar {
            AvatarUpdate::Keep => {}
            AvatarUpdate::Remove => upstream["avatar"] = Value::Null,
            AvatarUpdate::Replace(data_uri) => upstream["avatar"] = json!(data_uri),
        }
        Ok(upstream)
    }

