    /// messages.sendText story-reply context (contract 1.156, §4.154): the
    /// two optional keys ride the upstream frame verbatim — each only when
    /// the caller sent it, absence never becoming null — with no pair gate
    /// (a single-sided presence forwards as-is; the engine's storyContext
    /// parse owns the discipline) and no value-domain gate (a raw
    /// string-form timestamp forwards untouched, the 1.151 timestamp
    /// posture). The keyless body stays byte-identical to the pre-1.156
    /// shape.
    #[test]
    fn send_text_story_reply_context_rides_the_upstream_frame_verbatim() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let prepare =
            |text: &str, request: &str, author: Option<&str>, timestamp: Option<Value>| {
                match service
                    .prepare_send_text(
                        &account.id,
                        &conversation.id,
                        text,
                        request,
                        None,
                        None,
                        None,
                        None,
                        author.map(str::to_string),
                        timestamp,
                    )
                    .unwrap()
                {
                    PreparedSend::Dispatch { params, .. } => params,
                    PreparedSend::Existing(_) => panic!("new client request must dispatch"),
                }
            };

        // Both keys: the full story-reply context, byte-verbatim.
        assert_eq!(
            prepare(
                "story reply body",
                "req-story-reply-both",
                Some("22222222-2222-2222-2222-222222222222"),
                Some(json!(1_727_000_000_000u64)),
            ),
            json!({
                "account": "+15555550100",
                "message": "story reply body",
                "recipient": ["+15555550101"],
                "storyReplyAuthor": "22222222-2222-2222-2222-222222222222",
                "storyReplyTimestamp": 1_727_000_000_000u64,
            })
        );

        // Author only: the single-sided presence forwards as-is (the
        // pair-discipline refusal is the engine's face).
        let author_only = prepare(
            "author only",
            "req-story-reply-author",
            Some("22222222-2222-2222-2222-222222222222"),
            None,
        );
        assert_eq!(
            author_only["storyReplyAuthor"],
            json!("22222222-2222-2222-2222-222222222222")
        );
        assert!(author_only.get("storyReplyTimestamp").is_none());

        // Timestamp only, in a shape the engine refuses (a string stamp):
        // the raw value forwards untouched.
        let timestamp_only = prepare(
            "timestamp only",
            "req-story-reply-stamp",
            None,
            Some(json!("1727000000000")),
        );
        assert!(timestamp_only.get("storyReplyAuthor").is_none());
        assert_eq!(
            timestamp_only["storyReplyTimestamp"],
            json!("1727000000000")
        );

        // Neither key: the pre-1.156 wire shape, byte-identical.
        assert_eq!(
            prepare("plain body", "req-story-reply-plain", None, None),
            json!({
                "account": "+15555550100",
                "message": "plain body",
                "recipient": ["+15555550101"],
            })
        );
    }

    #[test]
    fn send_text_preview_rejects_deterministic_shape_violations() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let preview = |url: &str, title: &str| SendTextPreviewParams {
            url: url.into(),
            title: title.into(),
            description: None,
            image_data_uri: None,
            date: None,
        };
        // signal-cli requires the preview url to appear in the message body —
        // enforced here so the failure is a deterministic INVALID_REQUEST
        // instead of a late upstream send error.
        let url_absent = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "no link in here",
                "req-preview-absent",
                None,
                Some(vec![preview("https://example.com/a", "Example")]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(url_absent, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // A preview image is a data:image/ URI only — never a caller path.
        let path_image = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-path",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: None,
                    image_data_uri: Some("/etc/passwd".into()),
                    date: None,
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(path_image, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // Title is mandatory upstream.
        let empty_title = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-title",
                None,
                Some(vec![preview("https://example.com/a", "   ")]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(empty_title, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // A rejected preview leaves no pending row behind.
        assert!(
            service
                .store_ref()
                .message_by_client_request(&account.id, "req-preview-absent")
                .unwrap()
                .is_none()
        );
    }

    /// §4.126: the preview date rides the wire three ways — the upstream
    /// params carry `previewDate` (0 folds to absent, the official falsy
    /// posture), the pending row's rich persists the card metadata-only
    /// (never the image bytes), and the retry rebuild restores the card
    /// without the image.
    #[test]
    fn send_text_preview_date_rides_wire_row_and_retry() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-date",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: Some("A page".into()),
                    image_data_uri: Some("data:image/jpeg;base64,QUJD".into()),
                    date: Some(1_600_000_000_000),
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch {
                pending_id, params, ..
            } => {
                assert_eq!(params["previewDate"], json!(1_600_000_000_000_u64));
                pending_id
            }
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-preview-date")
            .unwrap()
            .unwrap();
        let rich = row.rich.as_ref().expect("a preview send arms the row rich");
        assert_eq!(rich.previews.len(), 1);
        assert_eq!(rich.previews[0].url, "https://example.com/a");
        assert_eq!(rich.previews[0].title.as_deref(), Some("Example"));
        assert_eq!(rich.previews[0].description.as_deref(), Some("A page"));
        assert_eq!(rich.previews[0].date, Some(1_600_000_000_000));
        assert!(
            rich.previews[0].image.is_none(),
            "the image data uri is transit-only, never a stored byte"
        );

        // The retry rebuild restores the card, metadata-only.
        service.complete_send_failed(&pending_id).unwrap();
        let params = match service
            .prepare_retry_text(&account.id, &conversation.id, "req-preview-date")
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("retry must re-dispatch the same row"),
        };
        assert_eq!(params["previewUrl"], json!("https://example.com/a"));
        assert_eq!(params["previewDate"], json!(1_600_000_000_000_u64));
        assert!(
            params.get("previewImage").is_none(),
            "the retried card re-sends metadata-only; previewImage is independently optional"
        );

        // A zero stamp folds to absent everywhere (the falsy posture).
        let params = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-date-zero",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: None,
                    image_data_uri: None,
                    date: Some(0),
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        assert!(
            params.get("previewDate").is_none(),
            "0 folds to absent — the key stays off the frame"
        );
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-preview-date-zero")
            .unwrap()
            .unwrap();
        assert_eq!(row.rich.as_ref().unwrap().previews[0].date, None);

        // The u64 type fails negative, fractional, and non-integer stamps at
        // params deserialization (fail-closed); 0 parses and folds later.
        let base = json!({
            "url": "https://example.com/a",
            "title": "Example",
        });
        for (label, date) in [
            ("negative", json!(-1)),
            ("fractional", json!(1.5)),
            ("string", json!("soon")),
        ] {
            let mut value = base.clone();
            value["date"] = date;
            assert!(
                serde_json::from_value::<SendTextPreviewParams>(value).is_err(),
                "{label} date must fail deserialization"
            );
        }
        let zero = serde_json::from_value::<SendTextPreviewParams>(json!({
            "url": "https://example.com/a",
            "title": "Example",
            "date": 0,
        }))
        .unwrap();
        assert_eq!(zero.date, Some(0));
    }

    /// §4.127: the blur placeholder rides the pending descriptor (singular
    /// and plural), fails closed on empty and over-bound values, and never
    /// reaches the upstream params — the engine's data-URI attachment
    /// channel has no blurHash key, so the placeholder is the sender's own
    /// bubble face only.
    #[test]
    fn send_attachment_blur_hash_rides_descriptor_and_stays_off_upstream() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw=="; // 16 raw bytes
        let placeholder = "LEHV6nWB2yk8pyo0adR*.7kCMdnj";

        // Singular: the descriptor carries it, the upstream frame does not.
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-1",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("see attachment"),
                None,
                false,
                false,
                Some(placeholder),
                false,
            )
            .unwrap();
        match &prepared {
            PreparedSend::Dispatch { params, .. } => {
                assert!(
                    params.get("blurHash").is_none(),
                    "the upstream data-URI channel has no blurHash key"
                );
            }
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        }
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-blur-1")
            .unwrap()
            .unwrap();
        assert_eq!(row.attachments[0].blur_hash.as_deref(), Some(placeholder));

        // Plural: the per-entry key rides its own descriptor.
        let entries = vec![MessagesSendAttachmentEntry {
            data_base64: b64.to_string(),
            size_bytes: 16,
            filename: Some("notes.txt".into()),
            content_type: Some("text/plain".into()),
            blur_hash: Some("abc123".into()),
            gif: false,
        }];
        let prepared = service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-2",
                &entries,
                None,
                None,
            )
            .unwrap();
        assert!(matches!(prepared, PreparedSend::Dispatch { .. }));
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-blur-2")
            .unwrap()
            .unwrap();
        assert_eq!(row.attachments[0].blur_hash.as_deref(), Some("abc123"));

        // Fail closed before the pending row: empty and over-bound values.
        for (label, value) in [("empty", Some("")), ("over-bound", Some(&"x".repeat(129)))] {
            let error = service
                .prepare_send_attachment(
                    &account.id,
                    &AttachmentSendTarget::Conversation(&conversation.id),
                    "req-blur-bad",
                    b64,
                    16,
                    Some("notes.txt"),
                    Some("text/plain"),
                    None,
                    None,
                    false,
                    false,
                    value,
                    false,
                )
                .unwrap_err();
            assert!(
                matches!(error, ServiceError::Api(ref e) if e.code == "INVALID_REQUEST"),
                "{label} blurHash must answer INVALID_REQUEST"
            );
            assert!(
                service
                    .store_ref()
                    .message_by_client_request(&account.id, "req-blur-bad")
                    .unwrap()
                    .is_none(),
                "{label} blurHash leaves no row behind"
            );
        }
        // The plural face fails closed the same way.
        let bad_entries = vec![MessagesSendAttachmentEntry {
            data_base64: b64.to_string(),
            size_bytes: 16,
            filename: None,
            content_type: None,
            blur_hash: Some(String::new()),
            gif: false,
        }];
        let error = service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-bad-multi",
                &bad_entries,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref e) if e.code == "INVALID_REQUEST"));
    }

    /// §4.123: the automatic queue enrolls exactly the definitive-error
    /// network classes, each arm on its own beat. `ServerUnavailable` /
    /// `Upstream` arm the curve in the same settlement; `RateLimited`
    /// (contract 1.143, §4.139) arms the Retry-After beat — the server
    /// answered "wait", so the row waits the official default minute, not
    /// the 190 ms curve head that would hammer again almost immediately.
    /// Every other engine error class settles the row plain `failed` with
    /// no schedule — the proof / identity families are the server stopping
    /// the send with a product judgment attached, the structured-code
    /// families mix deterministic refusals, and the unknown outcome (whose
    /// funnel arm never schedules) is the red line itself.
    #[test]
    fn retry_queue_enrolls_only_the_eligible_error_classes() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let face = |service: &ConnectorService, id: &str| {
            service
                .store_ref()
                .conn()
                .query_row(
                    "SELECT status, first_send_attempted_at, retry_attempt_count,
                            next_attempt_at
                     FROM messages WHERE id=?1",
                    params![id],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, Option<i64>>(1)?,
                            row.get::<_, i64>(2)?,
                            row.get::<_, Option<i64>>(3)?,
                        ))
                    },
                )
                .unwrap()
        };
        let enrollable = [
            EngineError::ServerUnavailable,
            EngineError::Upstream { cause: None },
        ];
        for (index, error) in enrollable.iter().enumerate() {
            let request = format!("req-enroll-{index}");
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    &request,
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            let events = service
                .complete_send_failed_for_engine(&pending_id, error)
                .unwrap();
            assert_eq!(events.len(), 1, "the failed transition emits");
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert!(
                first.is_some() && next.is_some() && count == 1,
                "{error:?} must arm the schedule"
            );
        }
        // The rate-limit arm: enrolled, but on the Retry-After beat — the
        // official one-minute default this wire falls back to, decisively
        // not the 190 ms curve head.
        {
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    "req-enroll-ratelimit",
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            let settled_at = now_ms();
            let events = service
                .complete_send_failed_for_engine(&pending_id, &EngineError::RateLimited)
                .unwrap();
            assert_eq!(events.len(), 1, "the failed transition emits");
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert!(first.is_some(), "the rate-limit arm stamps the window");
            assert_eq!(count, 1);
            let next = next.expect("the rate-limit arm arms the schedule");
            assert!(
                next >= (settled_at + crate::store::RATE_LIMIT_RETRY_AFTER_MS - 1_000) as i64
                    && next
                        <= (settled_at + crate::store::RATE_LIMIT_RETRY_AFTER_MS + 1_000) as i64,
                "the beat is the Retry-After default, not the curve: {next}"
            );
        }
        let refused = [
            EngineError::ProofRequired,
            EngineError::IdentityUnverified,
            EngineError::UpstreamCode {
                code: "STICKER_PACK_INVALID",
                data: None,
            },
            EngineError::Timeout,
            EngineError::NotRunning,
            EngineError::Unauthorized,
            EngineError::UnknownOutcome,
        ];
        for (index, error) in refused.iter().enumerate() {
            let request = format!("req-refuse-{index}");
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    &request,
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            service
                .complete_send_failed_for_engine(&pending_id, error)
                .unwrap();
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert_eq!(
                (first, count, next),
                (None, 0, None),
                "{error:?} must settle plain failed with no schedule"
            );
        }
    }

    /// Contract 1.143 (§4.139): the three-arm classification itself — the
    /// rate-limit family on the Retry-After beat, the transport family on
    /// the curve, and every other class (the deterministic structured
    /// refusals, the proof/identity gates, the timeout family, and the
    /// unknown red line) plain `None`.
    #[test]
    fn auto_retry_schedule_classifies_the_three_arms() {
        use crate::store::SendRetrySchedule;
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::RateLimited),
            SendRetrySchedule::RateLimit
        );
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::ServerUnavailable),
            SendRetrySchedule::Backoff
        );
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::Upstream { cause: None }),
            SendRetrySchedule::Backoff
        );
        for error in [
            EngineError::ProofRequired,
            EngineError::IdentityUnverified,
            EngineError::UpstreamCode {
                code: "STICKER_PACK_INVALID",
                data: None,
            },
            EngineError::Timeout,
            EngineError::NotRunning,
            EngineError::Unauthorized,
            EngineError::UnknownOutcome,
        ] {
            assert_eq!(
                ConnectorService::auto_retry_schedule(&error),
                SendRetrySchedule::None,
                "{error:?} carries no automatic follow-up"
            );
        }
    }

    /// The unknown red line at the store layer: an unknown settlement
    /// retires any schedule the row might carry, so an unknown row can
    /// never be claimed (AGENTS.md: unknown outcomes are never retried
    /// automatically).
    #[test]
    fn unknown_outcome_retires_any_stale_retry_schedule() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "hello",
                "req-unknown-face",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        // A stale schedule on a pending row (a hand-edited or restarted-over
        // store shape): the unknown settlement must sweep it.
        service
            .store_ref()
            .conn()
            .execute(
                "UPDATE messages SET first_send_attempted_at=?2, retry_attempt_count=3,
                        next_attempt_at=?3
                 WHERE id=?1",
                params![pending_id, 1_000i64, 2_000i64],
            )
            .unwrap();
        service.complete_send_unknown(&pending_id).unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-unknown-face")
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "unknown");
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT first_send_attempted_at, retry_attempt_count, next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, Option<i64>>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, Option<i64>>(2)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(face, (None, 0, None));
    }

    /// The §4.123 drain rebuild is the §4.26 manual rebuild: a claimed row
    /// re-dispatches the SAME row with the persisted text, and the send
    /// settlement completes it, clears the queue face, and leaves the
    /// history at exactly one row.
    #[test]
    fn outbox_claim_rebuilds_the_manual_retry_dispatch() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "queued text",
                "req-outbox-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        // Due-ify: claim past the 190 ms first beat (the schedule is
        // settle-time + 190 ms; the claim instant must stay inside the
        // 24 h window, so this is a real-clock +5 s, not an arbitrary
        // far-future stamp).
        let due_now = crate::link::now_ms() + 5_000;
        let claim = service.store_ref().claim_due_retries(due_now, 10).unwrap();
        assert_eq!(claim.len(), 1);
        let claim = &claim[0];
        assert_eq!(claim.message_id, pending_id);
        assert_eq!(claim.client_request_id, "req-outbox-1");
        let prepared = match service.prepare_outbox_retry_text(claim).unwrap() {
            PreparedSend::Dispatch {
                pending_id, params, ..
            } => {
                assert_eq!(pending_id, claim.message_id, "the same row re-dispatches");
                params
            }
            PreparedSend::Existing(_) => panic!("a claim rebuilds a dispatch, never an existing"),
        };
        assert_eq!(prepared["message"], json!("queued text"));
        assert_eq!(prepared["account"], json!("+15555550100"));
        // Settlement completes the SAME row and clears the queue face.
        let (sent, _) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 777, None)
            .unwrap();
        assert_eq!(sent.status, "sent");
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count,
                        next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<i64>>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(face, ("sent".into(), None, 0, None));
        let rows = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        assert_eq!(
            rows.len(),
            1,
            "the history stays one row per logical message"
        );
    }

    /// §4.134: the captioned attachment send never enters the §4.123 queue —
    /// the eligibility gate reads the row's attachment face beside its body,
    /// so a caption no longer smuggles an attachment row into a rebuild that
    /// would resend the words without the bytes. A sibling text row enrolls
    /// beside it and the claim takes only that one.
    #[test]
    fn retry_queue_never_enrolls_an_attachment_caption_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let attachment_pending = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-caption-1",
                "YXR0YWNobWVudCBieXRlcw==",
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("see attachment"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        let text_pending = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "plain queued text",
                "req-caption-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        // Both rows fail with the same retryable class; only the text row
        // may arm a schedule.
        service
            .complete_send_failed_for_engine(&attachment_pending, &EngineError::ServerUnavailable)
            .unwrap();
        service
            .complete_send_failed_for_engine(&text_pending, &EngineError::ServerUnavailable)
            .unwrap();
        let face = |service: &ConnectorService, id: &str| {
            service
                .store_ref()
                .conn()
                .query_row(
                    "SELECT status, first_send_attempted_at, retry_attempt_count, next_attempt_at
                     FROM messages WHERE id=?1",
                    params![id],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, Option<i64>>(1)?,
                            row.get::<_, i64>(2)?,
                            row.get::<_, Option<i64>>(3)?,
                        ))
                    },
                )
                .unwrap()
        };
        assert_eq!(
            face(&service, &attachment_pending),
            ("failed".into(), None, 0, None),
            "the captioned attachment row settles plain-failed, schedule retired"
        );
        let (_, first, count, next) = face(&service, &text_pending);
        assert!(
            first.is_some() && count == 1 && next.is_some(),
            "the text row enrolls"
        );

        // The claim takes exactly the text row; the attachment row is not in
        // the queue and not flipped.
        let due_now = crate::link::now_ms() + 5_000;
        let claims = service.store_ref().claim_due_retries(due_now, 10).unwrap();
        assert_eq!(claims.len(), 1, "{claims:?}");
        assert_eq!(claims[0].message_id, text_pending);
        assert_eq!(face(&service, &attachment_pending).0, "failed");
    }

    /// §4.134: a pre-revision attachment row that still carries a live
    /// schedule (hand-written, the enrolled-before-the-gate shape) is
    /// refused at claim time — the schedule retires, the row stays failed.
    /// A row that slips past into a rebuild settles the deterministic
    /// failure (queue face cleared, never a stranded pending), and the
    /// manual face answers RETRY_NOT_ALLOWED.
    #[test]
    fn retry_faces_refuse_an_attachment_row_and_settle_the_deterministic_failure() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-caption-legacy",
                "YXR0YWNobWVudCBieXRlcw==",
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("see attachment"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        // Hand-write the live schedule the pre-§4.134 gate would have armed.
        let now = crate::link::now_ms();
        service
            .store_ref()
            .conn()
            .execute(
                "UPDATE messages SET first_send_attempted_at=?2, retry_attempt_count=1,
                        next_attempt_at=?3
                 WHERE id=?1",
                params![pending_id, now as i64, (now + 190) as i64],
            )
            .unwrap();

        // The claim-time gate: no claim comes out, the schedule retires, the
        // row stays failed (never flipped pending).
        let claims = service
            .store_ref()
            .claim_due_retries(now + 5_000, 10)
            .unwrap();
        assert!(claims.is_empty(), "{claims:?}");
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count, next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<i64>>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(face, ("failed".into(), Some(now as i64), 1, None));

        // The rebuild-time belt: simulate the flip a pre-gate claim won (the
        // row is pending when the rebuild sees it) and hand the worker's
        // claim shape to the face. The refusal settles the deterministic
        // failure and clears the whole queue face.
        service
            .store_ref()
            .conn()
            .execute(
                "UPDATE messages SET status='pending' WHERE id=?1",
                params![pending_id],
            )
            .unwrap();
        let claim = crate::store::RetryClaim {
            message_id: pending_id.clone(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            client_request_id: "req-caption-legacy".into(),
            sent_at: row.sent_at,
        };
        assert!(service.prepare_outbox_retry_text(&claim).is_err());
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count, next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<i64>>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            face,
            ("failed".into(), None, 0, None),
            "the rebuild refusal settles the failure and retires the schedule"
        );

        // The manual face refuses the same family deterministically.
        let error = service
            .prepare_retry_text(&account.id, &conversation.id, "req-caption-legacy")
            .unwrap_err();
        assert!(
            matches!(error, ServiceError::Api(ref e) if e.code == "RETRY_NOT_ALLOWED"),
            "the manual face answers RETRY_NOT_ALLOWED, got {error:?}"
        );
    }

    #[test]
    fn retry_text_rearms_the_same_failed_row_and_guards_states() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // First send: prepare inserts the pending row, then it fails for real.
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "to retry",
                "retry-req-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service.complete_send_failed(&pending_id).unwrap();

        // Retry re-dispatches the SAME row — no second row is inserted.
        let params = match service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-1")
            .unwrap()
        {
            PreparedSend::Dispatch {
                pending_id: retry_pending_id,
                params,
                ..
            } => {
                assert_eq!(retry_pending_id, pending_id);
                params
            }
            PreparedSend::Existing(_) => panic!("retry must re-dispatch the same row"),
        };
        assert_eq!(params["message"], "to retry");
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "retry-req-1")
            .unwrap()
            .unwrap();
        assert_eq!(row.id, pending_id);
        assert_eq!(row.status, "pending");

        // Settlement completes the SAME row; the history stays one row.
        let (sent, _) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 777, None)
            .unwrap();
        assert_eq!(sent.status, "sent");
        let rows = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].id, pending_id);

        // §4.172: a settled row answers the idempotent REPLAY — the persisted
        // terminal row, no rearm, no second dispatch.
        let replay = service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-1")
            .unwrap();
        let PreparedSend::Existing(replay_row) = replay else {
            panic!("a settled row must replay its terminal answer");
        };
        assert_eq!(replay_row.id, pending_id);
        assert_eq!(replay_row.status, "sent");
        assert_eq!(replay_row.client_request_id.as_deref(), Some("retry-req-1"));
        let row_after_replay = service
            .store_ref()
            .message_by_client_request(&account.id, "retry-req-1")
            .unwrap()
            .unwrap();
        assert_eq!(
            row_after_replay.status, "sent",
            "the replay never touches the store"
        );

        // An unknown-outcome row is never retryable (no automatic or blind
        // resend of an unsettled wire outcome) — the §4.172 dedicated code.
        let unknown_pending = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "unknown outcome",
                "retry-req-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service.complete_send_unknown(&unknown_pending).unwrap();
        let unknown_retry = service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-2")
            .unwrap_err();
        assert!(
            matches!(unknown_retry, ServiceError::Api(ref error) if error.code == "RETRY_OUTCOME_UNKNOWN")
        );

        // A row already in flight answers RETRY_IN_FLIGHT (double click).
        service.complete_send_failed(&unknown_pending).unwrap();
        service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-2")
            .unwrap();
        let inflight = service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-2")
            .unwrap_err();
        assert!(
            matches!(inflight, ServiceError::Api(ref error) if error.code == "RETRY_IN_FLIGHT")
        );

        // Unknown clientRequestId -> MESSAGE_NOT_FOUND; a row addressed from
        // another conversation answers INVALID_REQUEST.
        let missing = service
            .prepare_retry_text(&account.id, &conversation.id, "retry-req-absent")
            .unwrap_err();
        assert!(matches!(
            missing,
            ServiceError::Store(StoreError::MessageNotFound)
        ));
        let other = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550103", "Peer2")
            .unwrap();
        let cross = service
            .prepare_retry_text(&account.id, &other.id, "retry-req-1")
            .unwrap_err();
        assert!(matches!(cross, ServiceError::Api(ref error) if error.code == "INVALID_REQUEST"));
    }

    /// §4.172: the idempotent replay answers the SAME terminal projection the
    /// first success answered — the settled row with the §4.171 outgoing-quote
    /// face attached, byte-shaped like the `complete_send_success` answer row —
    /// and the new read-only probe face answers the same settled state for
    /// the desktop's orphan sweep.
    #[test]
    fn retry_replay_answers_the_terminal_projection_and_the_probe_face_agrees() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut target = expire_record_fixture(&account.id, &conversation.id, "m-replay-target");
        target.sent_at = 500;
        target.text = Some("quoted body".into());
        service
            .store_ref()
            .insert_message(&target, None, None, false)
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "a reply",
                "req-replay-quote",
                Some("m-replay-target"),
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        let (settled, _) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 999, None)
            .unwrap();

        // The replay is byte-shaped like the first success answer: same row
        // id, same status, same quote projection.
        let replay = service
            .prepare_retry_text(&account.id, &conversation.id, "req-replay-quote")
            .unwrap();
        let PreparedSend::Existing(replay_row) = replay else {
            panic!("a settled row must replay its terminal answer");
        };
        assert_eq!(replay_row.id, settled.id);
        assert_eq!(replay_row.status, "sent");
        let replay_quote = replay_row.quote.expect("replay carries the quote pill");
        assert_eq!(replay_quote.id, 500);
        assert_eq!(replay_quote.text, "quoted body");

        // The read-only probe answers the same settled state (full read
        // projection), and refuses cross-conversation addressing.
        let probed = service
            .get_message_by_client_request(&account.id, &conversation.id, "req-replay-quote")
            .unwrap();
        assert_eq!(probed.id, settled.id);
        assert_eq!(probed.status, "sent");
        assert_eq!(probed.quote.expect("probe projects the quote").id, 500);
        let absent = service
            .get_message_by_client_request(&account.id, &conversation.id, "req-absent")
            .unwrap_err();
        assert!(matches!(
            &absent,
            ServiceError::Store(StoreError::MessageNotFound)
        ));
        // §4.174 (contract 1.174): the miss crosses into_api as
        // MESSAGE_NOT_FOUND verbatim — the desktop sweep probe distinguishes
        // not-found from transport failure, and folding this into
        // INTERNAL_ERROR would resurrect the false-failure flicker even
        // with the desktop admission gate open.
        assert_eq!(absent.into_api().code, "MESSAGE_NOT_FOUND");
        let other = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550103", "Peer2")
            .unwrap();
        let cross = service
            .get_message_by_client_request(&account.id, &other.id, "req-replay-quote")
            .unwrap_err();
        assert!(matches!(cross, ServiceError::Api(ref error) if error.code == "INVALID_REQUEST"));
    }

    /// Contract 1.69 outbound text styles (§4.62): more than 64 entries fail
    /// closed INVALID_REQUEST (non-retryable, no silent truncation — a caller
    /// bug must surface, not vanish), an unknown style vocabulary fails the
    /// whole request, a valid list projects 1:1 onto the engine `send`
    /// `textStyle` entry keys (style/start/length), an empty list leaves the
    /// upstream params without a `textStyle` key at all (byte-identical
    /// legacy wire), a styled pending row persists its ranges so the sender's
    /// bubble keeps its formatting across restarts, and a retry rebuilds the
    /// send without a `textStyle` key (documented deviation, §4.29 mentions
    /// precedent — the ranges are not persisted for retry rebuilds).
    #[test]
    fn send_text_styles_validate_project_persist_and_retry_bare() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        let style = |style: &str, start: u32, length: u32| SendTextStyleParams {
            style: style.to_string(),
            start,
            length,
        };
        let dispatch = |prepared: PreparedSend| match prepared {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("a fresh client request must dispatch"),
        };

        // Over-cap: deterministic INVALID_REQUEST, never a silent truncation.
        let over_cap = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "styled",
                "req-style-cap",
                None,
                None,
                None,
                Some((0..65).map(|index| style("BOLD", index, 1)).collect()),
                None,
                None,
            )
            .unwrap_err();
        assert!(
            matches!(&over_cap, ServiceError::Api(error) if error.code == "INVALID_REQUEST" && !error.retryable)
        );
        // A rejected style list leaves no pending row behind.
        assert!(
            service
                .store_ref()
                .message_by_client_request(&account.id, "req-style-cap")
                .unwrap()
                .is_none()
        );

        // Unknown style vocabulary: fail closed, no row.
        let unknown_style = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "styled",
                "req-style-unknown",
                None,
                None,
                None,
                Some(vec![style("BLINK", 0, 2)]),
                None,
                None,
            )
            .unwrap_err();
        assert!(
            matches!(&unknown_style, ServiceError::Api(error) if error.code == "INVALID_REQUEST" && !error.retryable)
        );
        assert!(
            service
                .store_ref()
                .message_by_client_request(&account.id, "req-style-unknown")
                .unwrap()
                .is_none()
        );

        // Valid list projects 1:1 onto the engine textStyle entry keys.
        let projected = dispatch(
            service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "styled body",
                    "req-style-ok",
                    None,
                    None,
                    None,
                    Some(vec![
                        style("BOLD", 0, 6),
                        style("SPOILER", 7, 4),
                        style("MONOSPACE", 7, 4),
                    ]),
                    None,
                    None,
                )
                .unwrap(),
        );
        let entries = projected["textStyle"].as_array().unwrap();
        assert_eq!(entries.len(), 3);
        assert_eq!(entries[0]["style"], "BOLD");
        assert_eq!(entries[0]["start"], 0);
        assert_eq!(entries[0]["length"], 6);
        assert_eq!(entries[1]["style"], "SPOILER");
        assert_eq!(entries[2]["style"], "MONOSPACE");

        // The styled pending row persists its ranges (sender echo across
        // restarts), and an empty list leaves no textStyle key at all.
        let stored = service
            .store_ref()
            .message_by_client_request(&account.id, "req-style-ok")
            .unwrap()
            .unwrap();
        let rich = stored.rich.as_ref().expect("styled row carries rich");
        assert_eq!(rich.text_styles.len(), 3);
        assert_eq!(rich.text_styles[0].style, "BOLD");
        assert!(!rich.view_once, "no view-once marker on a styled send");

        let bare = dispatch(
            service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "plain body",
                    "req-style-empty",
                    None,
                    None,
                    None,
                    Some(Vec::new()),
                    None,
                    None,
                )
                .unwrap(),
        );
        assert!(bare.get("textStyle").is_none());

        // Retry rebuilds the send without a textStyle key (documented
        // deviation): the failed styled row rearms and re-dispatches plain.
        service.complete_send_failed(&stored.id).unwrap();
        let retry_params = match service
            .prepare_retry_text(&account.id, &conversation.id, "req-style-ok")
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("retry must re-dispatch the same row"),
        };
        assert_eq!(retry_params["message"], "styled body");
        assert!(retry_params.get("textStyle").is_none());
    }

    #[test]
    fn outgoing_sync_reconciles_by_signal_timestamp_and_client_request_id() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "same text is not identity",
                "client-request-exact",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        let sync_receive = NormalizedReceive {
            timestamp: Some(99),
            content_kind: "syncMessage",
            direction: "outgoing",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("same text is not identity".into()),
            text_bytes: Some(25),
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            server_timestamp: None,
        };
        service
            .ingest_receive(sync_receive.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(
            service
                .list_messages(&account.id, &conversation.id, 10, None)
                .unwrap()
                .items
                .len(),
            2
        );

        let (sent, _) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 99, None)
            .unwrap();
        assert_eq!(
            sent.client_request_id.as_deref(),
            Some("client-request-exact")
        );
        let rows = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].id, pending_id);

        assert!(
            service
                .ingest_receive(sync_receive, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty()
        );
        assert_eq!(
            service
                .list_messages(&account.id, &conversation.id, 10, None)
                .unwrap()
                .items
                .len(),
            1
        );
    }

    /// Regression: the pending row can be gone when an upstream send completes
    /// (the account's rows were deleted in a race). The message may already be
    /// delivered, so the completion must surface a final, non-retryable state —
    /// never INTERNAL_ERROR with retryable=true on a mutating operation.
    #[test]
    fn missing_pending_row_at_send_completion_is_final_not_retryable() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "in flight",
                "req-race",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };

        // The deletion race: the account rows disappear while the upstream
        // send is still in flight.
        assert!(
            service
                .store_ref()
                .delete_account_cascade(&account.id)
                .unwrap()
        );

        let error = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 100, None)
            .unwrap_err();
        let ServiceError::Api(api) = error else {
            panic!("missing pending row must be an API error, got {error:?}");
        };
        assert_eq!(api.code, "SEND_OUTCOME_UNKNOWN");
        assert!(!api.retryable);

        // A pending id that never existed lands on the same non-retryable path.
        let error =
            match service.complete_send_success("absent", &account.id, &conversation.id, 100, None)
            {
                Err(ServiceError::Api(api)) => api,
                other => panic!("missing pending row must fail, got {other:?}"),
            };
        assert_eq!(error.code, "SEND_OUTCOME_UNKNOWN");
        assert!(!error.retryable);
    }

