    /// Deterministic rejections at validation time: unknown target, own
    /// not-yet-sent message, group message (member address is not persisted),
    /// and a message from another conversation. None of them may leave a
    /// pending row behind — the same clientRequestId must re-validate as new.
    #[test]
    fn unresolvable_quotes_are_rejected_before_any_pending_row_exists() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // Unknown quote target -> MESSAGE_NOT_FOUND, non-retryable.
        let api = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "reply",
                "req-quote-missing",
                Some("no-such-message"),
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap_err()
            .into_api();
        assert_eq!(api.code, "MESSAGE_NOT_FOUND");
        assert!(!api.retryable);

        // The rejection left no pending row: the same clientRequestId is a
        // fresh dispatch, not an idempotent replay of a stuck pending record.
        assert!(matches!(
            service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "reply",
                    "req-quote-missing",
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap(),
            PreparedSend::Dispatch { .. }
        ));

        // Quoting our own still-pending message would misquote upstream (its
        // sent_at is a local clock value until the send completes).
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "in flight",
                "req-pending",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        assert!(matches!(
            service.prepare_send_text(
                &account.id,
                &conversation.id,
                "quote pending",
                "req-quote-pending",
                Some(&pending_id), None,
             None, None, None, None),
            Err(ServiceError::Api(error)) if error.code == "INVALID_REQUEST" && !error.retryable
        ));

        // A group incoming message's author address is not persisted (only a
        // local sender hash), so the quote cannot be constructed upstream.
        let group_events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(900),
                    content_kind: "dataMessage",
                    direction: "incoming",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: Some("+15555550105".into()),
                    source_uuid: None,
                    peer_name: None,
                    group_id: Some("group-one".into()),
                    text: Some("group text".into()),
                    text_bytes: Some(10),
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: None,
                    server_guid: None,
                    server_timestamp: None,
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let group_message = group_events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .unwrap();
        assert!(matches!(
            service.prepare_send_text(
                &account.id,
                &group_message.conversation_id,
                "quote group",
                "req-quote-group",
                Some(&group_message.id), None,
             None, None, None, None),
            Err(ServiceError::Api(error)) if error.code == "INVALID_REQUEST" && !error.retryable
        ));

        // A message from another conversation is not a valid quote target here.
        assert!(matches!(
            service.prepare_send_text(
                &account.id,
                &conversation.id,
                "cross quote",
                "req-quote-cross",
                Some(&group_message.id),
                None,
                None,
                None,
                None,
                None,
            ),
            Err(ServiceError::Store(StoreError::MessageNotFound))
        ));
    }

    /// messages.remoteDelete resolves the local row to the upstream addressing:
    /// only an own outgoing `sent` row qualifies, its upstream-assigned
    /// `sent_at` becomes `targetTimestamp`, and the conversation's kind
    /// selects `recipient` (direct) vs `groupId` (group) — the same addressing
    /// shape as `send` (docs/remote-delete-l2-plan.md §3.2).
    #[test]
    fn remote_delete_maps_sent_outgoing_rows_to_upstream_params() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);

        // Direct conversation: recipient = [peer_key].
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let direct_id = match service
            .prepare_send_text(
                &account.id,
                &direct.id,
                "delete me",
                "req-rd-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&direct_id, &account.id, &direct.id, 777, None)
            .unwrap();
        let prepared = service
            .prepare_remote_delete(&account.id, &direct.id, &direct_id)
            .unwrap();
        assert_eq!(prepared.params["account"], json!("+15555550100"));
        assert_eq!(prepared.params["targetTimestamp"], json!(777));
        assert_eq!(prepared.params["recipient"], json!(["+15555550101"]));
        assert!(prepared.params.get("groupId").is_none());
        assert_eq!(prepared.account_id, account.id);
        assert_eq!(prepared.conversation_id, direct.id);
        assert_eq!(prepared.message_id, direct_id);

        // Group conversation: groupId = peer_key, no recipient.
        service
            .sync_accounts_from_numbers(
                &[("+15555550101".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "Z3JvdXAtaWQ=", "group")
            .unwrap();
        let group_message_id = match service
            .prepare_send_text(
                &account.id,
                &group.id,
                "group delete",
                "req-rd-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&group_message_id, &account.id, &group.id, 888, None)
            .unwrap();
        let prepared = service
            .prepare_remote_delete(&account.id, &group.id, &group_message_id)
            .unwrap();
        assert_eq!(prepared.params["targetTimestamp"], json!(888));
        assert_eq!(prepared.params["groupId"], json!("Z3JvdXAtaWQ="));
        assert!(prepared.params.get("recipient").is_none());
    }

    /// The eligibility guard is deterministic and local: pending, failed and
    /// unknown rows (their sent_at is a local clock value, not a protocol
    /// identity) and incoming rows all answer MESSAGE_NOT_FOUND before any
    /// upstream call — the same rule as quote resolution.
    #[test]
    fn remote_delete_rejects_rows_without_a_protocol_identity() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "in flight",
                "req-rd-p",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        for status in ["pending", "failed", "unknown"] {
            service
                .store_ref()
                .update_message_status(&pending_id, status, None)
                .unwrap();
            assert!(
                service
                    .prepare_remote_delete(&account.id, &conversation.id, &pending_id)
                    .is_err(),
                "a {status} row must not be deletable"
            );
        }

        // The incoming row of the same conversation is not deletable either.
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(50),
                    content_kind: "dataMessage",
                    direction: "incoming",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: Some("+15555550101".into()),
                    source_uuid: None,
                    peer_name: None,
                    group_id: None,
                    text: Some("peer text".into()),
                    text_bytes: Some(9),
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: None,
                    server_guid: None,
                    server_timestamp: None,
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let incoming = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .unwrap();
        let incoming_error = service
            .prepare_remote_delete(&account.id, &conversation.id, &incoming.id)
            .unwrap_err();
        assert_eq!(incoming_error.into_api().code, "MESSAGE_NOT_FOUND");

        // A never-existing row, conversation, or account answer their own
        // deterministic codes.
        assert_eq!(
            service
                .prepare_remote_delete(&account.id, &conversation.id, "absent-message")
                .unwrap_err()
                .into_api()
                .code,
            "MESSAGE_NOT_FOUND"
        );
        assert_eq!(
            service
                .prepare_remote_delete(&account.id, "absent-conversation", "anything")
                .unwrap_err()
                .into_api()
                .code,
            "CONVERSATION_NOT_FOUND"
        );
        assert_eq!(
            service
                .prepare_remote_delete("absent-account", "absent-conversation", "anything")
                .unwrap_err()
                .into_api()
                .code,
            "ACCOUNT_NOT_FOUND"
        );
    }

    /// messages.sendReaction resolves the local row to the upstream
    /// addressing: the target author follows the row direction — the linked
    /// account's own number for a `sent` outgoing row, the peer for an
    /// incoming direct row — and the conversation's kind selects `recipient`
    /// vs `groupId` (docs/remote-delete-l2-plan.md §3.2 shape, contract
    /// revision 1.7). remove passes through as an explicit boolean.
    #[test]
    fn send_reaction_maps_rows_to_the_direction_derived_target_author() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // Outgoing `sent` row: targetAuthor is the linked account itself.
        let sent_id = match service
            .prepare_send_text(
                &account.id,
                &direct.id,
                "react to me",
                "req-sr-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&sent_id, &account.id, &direct.id, 777, None)
            .unwrap();
        let prepared = service
            .prepare_send_reaction(&account.id, &direct.id, &sent_id, "👍", false)
            .unwrap();
        assert_eq!(prepared.params["account"], json!("+15555550100"));
        assert_eq!(prepared.params["emoji"], json!("👍"));
        assert_eq!(prepared.params["remove"], json!(false));
        assert_eq!(prepared.params["targetAuthor"], json!("+15555550100"));
        assert_eq!(prepared.params["targetTimestamp"], json!(777));
        assert_eq!(prepared.params["recipient"], json!(["+15555550101"]));
        assert!(prepared.params.get("groupId").is_none());
        assert_eq!(prepared.account_id, account.id);
        assert_eq!(prepared.conversation_id, direct.id);
        assert_eq!(prepared.message_id, sent_id);

        // Incoming row (direct chat): targetAuthor is the peer and the
        // envelope timestamp is the protocol identity.
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(50),
                    content_kind: "dataMessage",
                    direction: "incoming",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: Some("+15555550101".into()),
                    source_uuid: None,
                    peer_name: None,
                    group_id: None,
                    text: Some("peer text".into()),
                    text_bytes: Some(9),
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: None,
                    server_guid: None,
                    server_timestamp: None,
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let incoming = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .unwrap();
        let prepared = service
            .prepare_send_reaction(&account.id, &direct.id, &incoming.id, "🎉", true)
            .unwrap();
        assert_eq!(prepared.params["targetAuthor"], json!("+15555550101"));
        assert_eq!(prepared.params["targetTimestamp"], json!(50));
        assert_eq!(prepared.params["remove"], json!(true));

        // Group conversation: groupId addressing, no recipient.
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "Z3JvdXAtaWQ=", "group")
            .unwrap();
        let group_message_id = match service
            .prepare_send_text(
                &account.id,
                &group.id,
                "group react",
                "req-sr-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&group_message_id, &account.id, &group.id, 888, None)
            .unwrap();
        let prepared = service
            .prepare_send_reaction(&account.id, &group.id, &group_message_id, "👍", false)
            .unwrap();
        assert_eq!(prepared.params["targetAuthor"], json!("+15555550100"));
        assert_eq!(prepared.params["targetTimestamp"], json!(888));
        assert_eq!(prepared.params["groupId"], json!("Z3JvdXAtaWQ="));
        assert!(prepared.params.get("recipient").is_none());
    }

    /// The eligibility guard is deterministic and local: rows without a
    /// resolvable protocol identity (missing, pending/failed/unknown, system)
    /// answer MESSAGE_NOT_FOUND, and a group incoming row's author address is
    /// not persisted at all — a deterministic INVALID_REQUEST, never a
    /// mis-addressed upstream reaction (quote-resolution precedent).
    #[test]
    fn send_reaction_rejects_rows_without_a_resolvable_target_author() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "in flight",
                "req-sr-p",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        for status in ["pending", "failed", "unknown"] {
            service
                .store_ref()
                .update_message_status(&pending_id, status, None)
                .unwrap();
            let error = service
                .prepare_send_reaction(&account.id, &conversation.id, &pending_id, "👍", false)
                .unwrap_err();
            assert_eq!(
                error.into_api().code,
                "MESSAGE_NOT_FOUND",
                "a {status} row must not be reactable"
            );
        }

        // A group incoming message's author address is not persisted (only a
        // local sender hash), so the reaction cannot be addressed upstream.
        service
            .sync_accounts_from_numbers(
                &[("+15555550101".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-one", "group")
            .unwrap();
        let group_events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(900),
                    content_kind: "dataMessage",
                    direction: "incoming",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: Some("+15555550105".into()),
                    source_uuid: None,
                    peer_name: None,
                    group_id: Some("group-one".into()),
                    text: Some("group text".into()),
                    text_bytes: Some(10),
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: None,
                    server_guid: None,
                    server_timestamp: None,
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let group_message = group_events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .unwrap();
        assert_eq!(
            service
                .prepare_send_reaction(&account.id, &group.id, &group_message.id, "👍", false)
                .unwrap_err()
                .into_api()
                .code,
            "INVALID_REQUEST"
        );

        // A never-existing row, conversation, or account answer their own
        // deterministic codes.
        assert_eq!(
            service
                .prepare_send_reaction(&account.id, &conversation.id, "absent-message", "👍", false)
                .unwrap_err()
                .into_api()
                .code,
            "MESSAGE_NOT_FOUND"
        );
        assert_eq!(
            service
                .prepare_send_reaction(&account.id, "absent-conversation", "anything", "👍", false)
                .unwrap_err()
                .into_api()
                .code,
            "CONVERSATION_NOT_FOUND"
        );
        assert_eq!(
            service
                .prepare_send_reaction(
                    "absent-account",
                    "absent-conversation",
                    "anything",
                    "👍",
                    false
                )
                .unwrap_err()
                .into_api()
                .code,
            "ACCOUNT_NOT_FOUND"
        );
    }

    /// Receipt-advanced outgoing rows stay addressable: delivery/read
    /// receipts only advance `status` while `update_message_status` preserves
    /// the upstream `sent_at`, so a delivered or read row reacts with the
    /// same protocol identity it had at `sent` (official behavior — reacting
    /// to an already-delivered message is the common case).
    #[test]
    fn send_reaction_accepts_receipt_advanced_outgoing_rows() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let message_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "delivered then read",
                "req-sr-advance",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&message_id, &account.id, &conversation.id, 777, None)
            .unwrap();
        for status in ["sent", "delivered", "read"] {
            service
                .store_ref()
                .update_message_status(&message_id, status, None)
                .unwrap();
            let prepared = service
                .prepare_send_reaction(&account.id, &conversation.id, &message_id, "👍", false)
                .unwrap();
            assert_eq!(prepared.params["targetAuthor"], json!("+15555550100"));
            assert_eq!(prepared.params["targetTimestamp"], json!(777));
        }
    }

    /// 上行确认后的 complete 落库：own 回应以 account 为 actor 持久化，pill
    /// 带 mine=true、actor 标 self；remove=true 撤回后 pill 消失。app 的乐观
    /// 窗口结束后读侧仍一致（supervisor 侧另推 conversation.changed）。
    #[test]
    fn complete_send_reaction_persists_own_pill_and_removal() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let message_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "reaction target",
                "req-sr-complete",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&message_id, &account.id, &conversation.id, 888, None)
            .unwrap();
        let prepared = service
            .prepare_send_reaction(&account.id, &conversation.id, &message_id, "👍", false)
            .unwrap();
        assert!(
            service
                .complete_send_reaction(
                    &prepared.account_id,
                    &prepared.conversation_id,
                    &prepared.emoji,
                    prepared.remove,
                    prepared.target_sent_at,
                )
                .unwrap()
                .is_some()
        );
        let reactions = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &message_id)
            .unwrap()
            .unwrap()
            .reactions;
        assert_eq!(reactions.len(), 1);
        assert_eq!(reactions[0].emoji, "👍");
        assert!(reactions[0].mine);
        assert!(reactions[0].actors.iter().all(|actor| actor.is_self));

        let prepared = service
            .prepare_send_reaction(&account.id, &conversation.id, &message_id, "👍", true)
            .unwrap();
        service
            .complete_send_reaction(
                &prepared.account_id,
                &prepared.conversation_id,
                &prepared.emoji,
                prepared.remove,
                prepared.target_sent_at,
            )
            .unwrap();
        let reactions = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &message_id)
            .unwrap()
            .unwrap()
            .reactions;
        assert!(reactions.is_empty());
    }

    /// §4.171 outbound quote projection — the author ladder on the read
    /// faces: a direct incoming target quotes with the conversation peer,
    /// an addressable own outgoing target quotes with the linked account's
    /// number, and every unresolvable target degrades to absent (pending
    /// own row, missing row). The projection rides the list face and the
    /// single-row face alike; it is never stored.
    #[test]
    fn outgoing_quote_projection_follows_the_author_ladder_and_degrades_to_absent() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &conversation.id, "m-in");
        incoming.sent_at = 500;
        incoming.text = Some("hello from peer".into());
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();
        let mut own = expire_record_fixture(&account.id, &conversation.id, "m-out");
        own.direction = "outgoing";
        own.status = "sent";
        own.sender_id = account.id.clone();
        own.sent_at = 600;
        own.text = Some("my own line".into());
        service
            .store_ref()
            .insert_message(&own, None, None, false)
            .unwrap();
        let mut inflight = expire_record_fixture(&account.id, &conversation.id, "m-pending");
        inflight.direction = "outgoing";
        inflight.status = "pending";
        inflight.sender_id = account.id.clone();
        inflight.sent_at = 650;
        inflight.text = Some("still in flight".into());
        service
            .store_ref()
            .insert_message(&inflight, None, None, false)
            .unwrap();

        for (id, target, sent_at) in [
            ("m-quote-in", "m-in", 700),
            ("m-quote-out", "m-out", 710),
            ("m-quote-pending", "m-pending", 720),
            ("m-quote-gone", "m-gone", 730),
        ] {
            let mut record = expire_record_fixture(&account.id, &conversation.id, id);
            record.direction = "outgoing";
            record.status = "sent";
            record.sender_id = account.id.clone();
            record.sent_at = sent_at;
            record.text = Some("reply body".into());
            record.quote_message_id = Some(target.into());
            service
                .store_ref()
                .insert_message(&record, None, None, false)
                .unwrap();
        }

        let page = service
            .store_ref()
            .list_messages(&account.id, &conversation.id, 50, None)
            .unwrap();
        let quote_of = |page: &crate::store::Page<MessageRecord>, id: &str| {
            page.items
                .iter()
                .find(|item| item.id == id)
                .unwrap()
                .quote
                .clone()
        };
        let quoted_in = quote_of(&page, "m-quote-in").expect("direct incoming target resolves");
        assert_eq!(quoted_in.id, 500);
        assert_eq!(quoted_in.author, "+15555550101");
        assert_eq!(quoted_in.text, "hello from peer");
        let quoted_out = quote_of(&page, "m-quote-out").expect("own sent target resolves");
        assert_eq!(quoted_out.id, 600);
        assert_eq!(quoted_out.author, "+15555550100");
        assert_eq!(quoted_out.text, "my own line");
        assert!(
            quote_of(&page, "m-quote-pending").is_none(),
            "a pending own target never addresses"
        );
        assert!(
            quote_of(&page, "m-quote-gone").is_none(),
            "a missing target stays absent"
        );
        // The single-row read face carries the same projection.
        let single = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, "m-quote-in")
            .unwrap()
            .unwrap();
        assert_eq!(single.quote.as_ref().unwrap().author, "+15555550101");
    }

    /// §4.171 retraction and group guards: a group incoming target only
    /// persists a local sender hash (no addressable author) and a
    /// remote-deleted direct target keeps its body bytes but its deletion
    /// face is the truth — both degrade to absent, never resurrect content
    /// or guess an author.
    #[test]
    fn group_and_retracted_targets_never_project() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "ZmFrZS1ncm91cC0x", "Fixture Group")
            .unwrap();
        let mut member_line = expire_record_fixture(&account.id, &group.id, "g-target");
        member_line.sent_at = 900;
        member_line.text = Some("group chatter".into());
        service
            .store_ref()
            .insert_message(&member_line, None, None, false)
            .unwrap();
        let mut g_reply = expire_record_fixture(&account.id, &group.id, "g-quote");
        g_reply.direction = "outgoing";
        g_reply.status = "sent";
        g_reply.sender_id = account.id.clone();
        g_reply.sent_at = 910;
        g_reply.quote_message_id = Some("g-target".into());
        service
            .store_ref()
            .insert_message(&g_reply, None, None, false)
            .unwrap();

        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut d_target = expire_record_fixture(&account.id, &direct.id, "d-target");
        d_target.sent_at = 920;
        d_target.text = Some("to be retracted".into());
        service
            .store_ref()
            .insert_message(&d_target, None, None, false)
            .unwrap();
        let mut d_reply = expire_record_fixture(&account.id, &direct.id, "d-quote");
        d_reply.direction = "outgoing";
        d_reply.status = "sent";
        d_reply.sender_id = account.id.clone();
        d_reply.sent_at = 930;
        d_reply.quote_message_id = Some("d-target".into());
        service
            .store_ref()
            .insert_message(&d_reply, None, None, false)
            .unwrap();
        service
            .store_ref()
            .mark_remote_deleted(&account.id, &direct.id, 920, "peer")
            .unwrap();

        let group_page = service
            .store_ref()
            .list_messages(&account.id, &group.id, 50, None)
            .unwrap();
        assert!(
            group_page
                .items
                .iter()
                .find(|item| item.id == "g-quote")
                .unwrap()
                .quote
                .is_none(),
            "a group incoming target has no addressable author"
        );
        let direct_page = service
            .store_ref()
            .list_messages(&account.id, &direct.id, 50, None)
            .unwrap();
        assert!(
            direct_page
                .items
                .iter()
                .find(|item| item.id == "d-quote")
                .unwrap()
                .quote
                .is_none(),
            "a remote-deleted target quotes as nothing"
        );
    }

