    /// username.lookup bounds the batch and forwards entries verbatim
    /// (contract 1.74, §4.65).
    #[test]
    fn username_lookup_preparation_bounds_batch_and_shares_frame() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let params = |usernames: Vec<String>| UsernameLookupParams {
            account_id: account.id.clone(),
            usernames,
        };

        // Empty and over-cap batches.
        let error = service
            .prepare_username_lookup(&params(vec![]))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let over = vec!["kt.user".to_string(); USERNAME_LOOKUP_MAX_ENTRIES + 1];
        let error = service.prepare_username_lookup(&params(over)).unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        // Entry bound: 65 chars.
        let error = service
            .prepare_username_lookup(&params(vec!["k".repeat(65)]))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        // Entries forwarded verbatim.
        assert_eq!(
            service
                .prepare_username_lookup(&params(vec![
                    "kt_test.01".into(),
                    "https://signal.me/#eu".into()
                ]))
                .unwrap(),
            json!({
                "account": "+15555550100",
                "usernames": ["kt_test.01", "https://signal.me/#eu"],
            })
        );
    }

    /// phone.lookup (contract 1.164, §4.162) bounds the batch and the E.164
    /// shape before any engine traffic, and the frame carries the resolved
    /// signal account under the engine's `account` key with the numbers
    /// verbatim.
    #[test]
    fn phone_lookup_preparation_bounds_batch_and_gates_the_e164_shape() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let params = |numbers: Vec<String>| PhoneLookupParams {
            account: account.id.clone(),
            numbers,
        };

        // Empty and over-cap batches.
        let error = service.prepare_phone_lookup(&params(vec![])).unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let over = vec!["+15550000001".to_string(); PHONE_LOOKUP_MAX_ENTRIES + 1];
        let error = service.prepare_phone_lookup(&params(over)).unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        // The E.164 shape gate, rule by rule: the lower/upper digit bounds,
        // the leading +, the ASCII-digits-only body (a fullwidth digit is
        // not ASCII), no embedded separators, no double +.
        for malformed in [
            "15550000001",       // no leading +
            "+",                 // + alone
            "+155500",           // 6 digits — below the 7-digit floor
            "+1555000000000000", // 16 digits — above the 15-digit ceiling
            "+1555abc23456",     // letters
            "+1555 000 0001",    // embedded spaces
            "++15550000001",     // double +
            "+1555123456７",     // fullwidth digit (non-ASCII)
            "+1555-000-0001",    // dashes
        ] {
            let error = service
                .prepare_phone_lookup(&params(vec![malformed.to_string()]))
                .unwrap_err();
            assert!(
                matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"),
                "malformed E.164 must refuse locally: {malformed}"
            );
        }
        // The gate boundaries pass: exactly 7 and exactly 15 digits.
        assert!(is_e164_phone_number_shape("+1555001"));
        assert!(is_e164_phone_number_shape(&format!("+{}", "1".repeat(15))));

        // The frame: the resolved signal account under `account`, the
        // numbers verbatim, nothing else.
        assert_eq!(
            service
                .prepare_phone_lookup(&params(vec!["+15551234567".into(), "+15557654321".into()]))
                .unwrap(),
            json!({
                "account": "+15555550100",
                "numbers": ["+15551234567", "+15557654321"],
            })
        );
    }

    /// The phone.lookup error faces ride the engine's literals with the
    /// contract-fixed retryability: INVALID deterministic, RATE_LIMITED
    /// carrying the promised {retryAfterSeconds} verbatim (retryability
    /// reasserted over the with_data default), SERVER_FAILED
    /// may-succeed-later — and every face has its schema-declared literal.
    #[test]
    fn phone_lookup_error_faces_carry_the_promised_retry_face() {
        let rate_limited = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PHONE_RATE_LIMITED",
            data: Some(json!({ "retryAfterSeconds": 42 })),
        })
        .into_api();
        assert_eq!(rate_limited.code, "PHONE_RATE_LIMITED");
        assert!(rate_limited.retryable);
        assert_eq!(rate_limited.data, Some(json!({ "retryAfterSeconds": 42 })));

        // A data-less RATE_LIMITED face keeps the contract-fixed
        // retryability without inventing a data object.
        let bare = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PHONE_RATE_LIMITED",
            data: None,
        })
        .into_api();
        assert!(bare.retryable);
        assert_eq!(bare.data, None);

        let invalid = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PHONE_INVALID",
            data: None,
        })
        .into_api();
        assert_eq!(invalid.code, "PHONE_INVALID");
        assert!(!invalid.retryable);

        let server_failed = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PHONE_SERVER_FAILED",
            data: None,
        })
        .into_api();
        assert_eq!(server_failed.code, "PHONE_SERVER_FAILED");
        assert!(server_failed.retryable);

        // The allowlist carries all three faces (the schema error enum's
        // code-side mirror is the consistency test).
        for code in ["PHONE_INVALID", "PHONE_RATE_LIMITED", "PHONE_SERVER_FAILED"] {
            assert!(
                crate::engine::ENGINE_STRUCTURED_ERROR_CODES_FOR_TESTS.contains(&code),
                "{code} must be allowlisted"
            );
        }
    }

    /// The username shape gate is exactly the desktop grammar: a focused
    /// rule-by-rule pass.
    #[test]
    fn validate_username_shape_mirrors_the_desktop_grammar() {
        for good in [
            "abc",           // minimal nickname
            &"a".repeat(32), // maximal nickname
            "kt_test",       // underscore nickname, bare (no discriminator)
            "_leading",      // underscore first
            "kt_test.01",    // discriminator, two-digit 0-leading form
            "kt_test.10",
            "kt_test.65536", // full digit run (range stays upstream authority)
            "a_b.99",
        ] {
            validate_username_shape(good)
                .unwrap_or_else(|error| panic!("expected {good} to pass: {error:?}"));
        }
        for bad in [
            "ab",             // below the 3-char nickname window
            &"a".repeat(33),  // above the 32-char nickname window
            "kt test",        // space
            "kt-Test",        // dash
            "1kt",            // leading digit
            "kt.",            // nickname 2 chars AND empty discriminator
            "kt..1",          // nickname 2 chars AND empty first discriminator
            "kt_test.01.2",   // dot inside the discriminator
            "kt_test.00",     // double zero
            "kt_test.000",    // triple zero
            "kt_test.0",      // 0-leading single digit (only exactly two digits allowed)
            "kt_test.012",    // 0-leading three digits
            "kt_test.65536x", // trailing letter inside the discriminator
        ] {
            assert!(
                validate_username_shape(bad).is_err(),
                "expected {bad} to fail"
            );
        }
    }

    // ---- Contract 1.52 (§4.50): group termination face ----

    /// prepare_groups_terminate resolves the group and answers the bare
    /// upstream payload (the pinned 0.14.8 `terminateGroup` dests); the
    /// refusal ladder answers before any upstream call — bad ids, an unknown
    /// conversation, and direct addressing. No capability gate: the face
    /// rides the engine's jsonRpc surface.
    #[test]
    fn groups_terminate_preparation_addresses_the_group_and_refuses_non_groups() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let terminate = |conversation_id: String| GroupsTerminateParams {
            account_id: account.id.clone(),
            conversation_id,
            operation_id: None,
        };
        assert_eq!(
            service
                .prepare_groups_terminate(&terminate(group.id.clone()))
                .unwrap(),
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
            })
        );
        // The operationId is validated by shape and never persisted; a legal
        // one changes nothing on the wire.
        assert_eq!(
            service
                .prepare_groups_terminate(&GroupsTerminateParams {
                    operation_id: Some("term-op-1".into()),
                    ..terminate(group.id.clone())
                })
                .unwrap(),
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
            })
        );
        let error = service
            .prepare_groups_terminate(&terminate(direct.id.clone()))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let missing = service
            .prepare_groups_terminate(&terminate("conv-absent".into()))
            .unwrap_err();
        assert!(matches!(
            missing,
            ServiceError::Store(StoreError::ConversationNotFound)
        ));
        let bad_operation = service
            .prepare_groups_terminate(&GroupsTerminateParams {
                operation_id: Some("x".repeat(MAX_OPAQUE_ID_BYTES + 1)),
                ..terminate(group.id.clone())
            })
            .unwrap_err();
        assert!(
            matches!(bad_operation, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"),
            "an over-bound operationId is a shape refusal: {bad_operation:?}"
        );
    }

    // ---- Contract 1.58 (§4.53): group join-request approval face ----

    /// groups.approveJoinRequests runs the full refusal ladder — empty
    /// members, oversized member arrays, per-entry shape violations, bad
    /// ids, an unknown conversation, direct addressing, and an over-bound
    /// audit id — and the valid call answers the honest
    /// CAPABILITY_UNAVAILABLE (the engine debt precedent — the fold must
    /// not disguise "cannot approve" as "nobody is requesting").
    #[test]
    fn groups_approve_join_requests_preparation_refuses_gaps_and_the_face() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let params = |conversation_id: String, members: Vec<String>, approve: bool| {
            GroupsApproveJoinRequestsParams {
                account_id: account.id.clone(),
                conversation_id,
                members,
                approve,
                operation_id: None,
            }
        };

        // The refusal ladder, each before any engine call.
        let empty = service
            .prepare_groups_approve_join_requests(&params(group.id.clone(), vec![], true))
            .unwrap_err();
        assert!(matches!(empty, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let direct_addressed = service
            .prepare_groups_approve_join_requests(&params(
                direct.id.clone(),
                vec!["+15555550102".into()],
                true,
            ))
            .unwrap_err();
        assert!(
            matches!(direct_addressed, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"),
            "a direct conversation is a shape refusal: {direct_addressed:?}"
        );
        let missing = service
            .prepare_groups_approve_join_requests(&params(
                "conv-absent".into(),
                vec!["+15555550102".into()],
                true,
            ))
            .unwrap_err();
        assert!(matches!(
            missing,
            ServiceError::Store(StoreError::ConversationNotFound)
        ));
        let bad_shape = service
            .prepare_groups_approve_join_requests(&params(
                group.id.clone(),
                vec![String::new()],
                true,
            ))
            .unwrap_err();
        assert!(matches!(bad_shape, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let oversized = service
            .prepare_groups_approve_join_requests(&params(
                group.id.clone(),
                (0..=MAX_GROUP_MEMBERS)
                    .map(|index| format!("+15555050{index:03}"))
                    .collect(),
                true,
            ))
            .unwrap_err();
        assert!(matches!(oversized, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        // The valid call: the honest capability gap after local
        // validation (CAPABILITY_UNAVAILABLE, retryable=false).
        let valid = service
            .prepare_groups_approve_join_requests(&params(
                group.id.clone(),
                vec!["+15555550101".into()],
                true,
            ))
            .unwrap_err();
        assert!(
            matches!(valid, ServiceError::Api(ref api) if api.code == "CAPABILITY_UNAVAILABLE" && !api.retryable),
            "the engine debt answers the capability gap: {valid:?}"
        );
    }

