    // ---- Contract 1.49 (§4.48): report spam face ----

    /// prepare_report_spam resolves the direct conversation's rows to the
    /// engine payload: only rows carrying a persisted serverGuid join
    /// `serverGuids` (order preserved, caller's id paired for the result
    /// projection); the refusal ladder answers before any upstream call —
    /// empty/oversized id lists, bad ids, unknown conversations, group
    /// addressing, a numeric peer with no recorded ACI mapping — while a
    /// UUID-shaped peer key addresses the report directly.
    #[test]
    fn report_spam_preparation_resolves_guid_rows_and_refuses_gaps() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);

        // A UUID-shaped peer key: the ACI itself, no mapping needed.
        let aci = "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10";
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", aci, "Peer")
            .unwrap();
        let mut guided = expire_record_fixture(&account.id, &direct.id, "m1");
        guided.server_guid = Some("guid-1".into());
        service
            .store_ref()
            .insert_message(&guided, None, None, true)
            .unwrap();
        let plain = expire_record_fixture(&account.id, &direct.id, "m2");
        service
            .store_ref()
            .insert_message(&plain, None, None, true)
            .unwrap();

        let params = |conversation_id: String, message_ids: Vec<String>| MessagesReportSpamParams {
            account_id: account.id.clone(),
            conversation_id,
            message_ids,
        };

        let prepared = service
            .prepare_report_spam(&params(
                direct.id.clone(),
                vec!["m1".into(), "m2".into(), "missing".into()],
            ))
            .unwrap();
        assert_eq!(
            prepared.upstream,
            json!({
                "account": "+15555550100",
                "targetAci": aci,
                "serverGuids": ["guid-1"],
            })
        );
        assert_eq!(
            prepared.pairs,
            vec![("m1".to_string(), "guid-1".to_string())]
        );

        // Empty and oversized id lists.
        let error = service
            .prepare_report_spam(&params(direct.id.clone(), Vec::new()))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let error = service
            .prepare_report_spam(&params(
                direct.id.clone(),
                (0..REPORT_SPAM_MESSAGE_IDS_LIMIT + 1)
                    .map(|index| format!("m{index}"))
                    .collect(),
            ))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        // Per-id bounds: an empty entry and an over-budget id.
        let error = service
            .prepare_report_spam(&params(direct.id.clone(), vec!["".into()]))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
        let error = service
            .prepare_report_spam(&params(
                direct.id.clone(),
                vec!["x".repeat(MAX_OPAQUE_ID_BYTES + 1)],
            ))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        // A numeric peer without a recorded ACI mapping refuses before any
        // upstream call — the report would mis-address upstream.
        let numeric = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550102", "Numeric")
            .unwrap();
        let error = service
            .prepare_report_spam(&params(numeric.id.clone(), vec!["m1".into()]))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api)
                if api.code == "INVALID_REQUEST" && !api.retryable));

        // The recorded ACI↔peer-key mapping resolves the numeric peer.
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "33333333-3333-3333-3333-333333333333",
                "+15555550102",
            )
            .unwrap();
        let prepared = service
            .prepare_report_spam(&params(numeric.id.clone(), vec!["m1".into()]))
            .unwrap();
        assert_eq!(
            prepared.upstream["targetAci"],
            json!("33333333-3333-3333-3333-333333333333")
        );

        // A group conversation refuses before any upstream call.
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let error = service
            .prepare_report_spam(&params(group.id.clone(), vec!["m1".into()]))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        // Unknown conversations answer the ladder step.
        let error = service
            .prepare_report_spam(&params("conv-absent".into(), vec!["m1".into()]))
            .unwrap_err();
        assert!(matches!(
            error,
            ServiceError::Store(StoreError::ConversationNotFound)
        ));
    }

    /// A group-update row mirrors the engine's post-change title into the
    /// conversation row (the summary riding conversation.changed already
    /// carries it), lands as a system row, and leaves the title untouched
    /// when the update carried no name material. A body-carrying update keeps
    /// its ordinary message row and still mirrors.
    #[test]
    fn ingest_group_update_mirrors_title_and_lands_a_system_row() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let group_update = NormalizedReceive {
            timestamp: Some(1727000000000),
            content_kind: "dataMessage",
            direction: "system",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: Some("Peer".into()),
            group_id: Some("group-id-1".into()),
            text: Some("群聊信息已更新".into()),
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: Some(crate::engine::NormalizedRich {
                is_group_update: true,
                group_name: Some("Fixture Group".into()),
                ..Default::default()
            }),
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(group_update.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .expect("group update row");
        assert_eq!(upserted.direction, "system");
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("title mirror event");
        assert_eq!(changed.title, "Fixture Group");
        assert_eq!(
            service
                .store_ref()
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .title,
            "Fixture Group"
        );

        // An update with no name material lands its row and converges nothing.
        let nameless = NormalizedReceive {
            timestamp: Some(1727000000001),
            rich: Some(crate::engine::NormalizedRich {
                is_group_update: true,
                ..Default::default()
            }),
            server_guid: None,
            server_timestamp: None,
            ..group_update.clone()
        };
        let events = service
            .ingest_receive(nameless, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            events
                .iter()
                .any(|event| matches!(event, HostSideEvent::MessageUpserted(_)))
        );
        assert_eq!(
            service
                .store_ref()
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .title,
            "Fixture Group"
        );

        // A body-carrying update is an ordinary incoming row — and still
        // mirrors the title.
        let with_body = NormalizedReceive {
            timestamp: Some(1727000000002),
            direction: "incoming",
            text: Some("renamed us".into()),
            rich: Some(crate::engine::NormalizedRich {
                is_group_update: true,
                group_name: Some("Renamed Group".into()),
                ..Default::default()
            }),
            server_guid: None,
            server_timestamp: None,
            ..group_update
        };
        let events = service
            .ingest_receive(with_body, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .expect("body row");
        assert_eq!(upserted.direction, "incoming");
        assert_eq!(
            service
                .store_ref()
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .title,
            "Renamed Group"
        );
    }

    /// The engine's groupUpdated projection (2026-10-06 engine batch; row half
    /// contract 1.92 §4.75): the mirror lands with the conversation.changed
    /// summary carrying the new timer (0 = off included) and the official
    /// timer-notice system row lands beside it — the §4.41 material and rich
    /// marker, no expire columns (the notice row never sweeps), the
    /// conversation-scoped unattributed sender when the envelope named no
    /// editor. A same-value event is a real upstream change envelope (the
    /// group revision advanced): the row lands for it too.
    #[test]
    fn ingest_group_timer_update_mirrors_state_and_lands_the_notice_row() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();

        let group_timer = NormalizedReceive {
            timestamp: Some(1727000000000),
            content_kind: "control",
            direction: "control",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            server_timestamp: None,
            peer_name: None,
            group_id: Some("group-id-1".into()),
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::GroupTimerUpdate {
                expire_timer_seconds: 3600,
                editor: None,
            }),
        };
        let events = service
            .ingest_receive(group_timer.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record.clone()),
                _ => None,
            })
            .expect("the timer notification lands as the official notice row");
        assert_eq!(upserted.conversation_id, conversation.id);
        assert_eq!(upserted.direction, "system");
        assert_eq!(upserted.status, "system");
        assert_eq!(
            upserted.text.as_deref(),
            Some("已更新消息定时消失：3600 秒"),
            "the row text is the §4.41 material verbatim"
        );
        assert!(
            upserted
                .rich
                .as_ref()
                .is_some_and(|rich| rich.is_expiration_update),
            "the row carries the §4.41 rich marker"
        );
        assert_eq!(upserted.expire_seconds, None, "the notice row never sweeps");
        assert_eq!(
            upserted.sender_id,
            stable_hash_id(&[&account.id, "group", "group-id-1"]),
            "an editor-less envelope keeps the unattributed conversation-scoped sender"
        );
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the mirror rides conversation.changed");
        assert_eq!(changed.id, conversation.id);
        assert_eq!(changed.expire_timer_seconds, Some(3600));
        assert_eq!(
            service
                .store_ref()
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .expire_timer_seconds,
            Some(3600)
        );

        // The off form stores 0 literally (the §4.41 setter discipline), never
        // NULL, and lands the close-form notice row.
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(1727000001000),
                    control: Some(ControlReceive::GroupTimerUpdate {
                        expire_timer_seconds: 0,
                        editor: None,
                    }),
                    ..group_timer.clone()
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the off form notifies too");
        assert_eq!(changed.expire_timer_seconds, Some(0));
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record.clone()),
                _ => None,
            })
            .expect("the off form lands the close-form row");
        assert_eq!(upserted.text.as_deref(), Some("已更新消息定时消失：已关闭"));
        assert_eq!(
            service
                .store_ref()
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .expire_timer_seconds,
            Some(0)
        );

        // A same-value event is a real upstream change envelope: the row lands
        // for it too (the official timeline narrates the change, not the diff).
        let same_value = NormalizedReceive {
            timestamp: Some(1727000002000),
            control: Some(ControlReceive::GroupTimerUpdate {
                expire_timer_seconds: 0,
                editor: None,
            }),
            ..group_timer
        };
        let events = service
            .ingest_receive(same_value.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            events
                .iter()
                .any(|event| matches!(event, HostSideEvent::MessageUpserted(_))),
            "the same-value envelope still lands its notice row"
        );

        // A replayed envelope (same identity tuple) dedupes through the row
        // identity and converges nothing a second time.
        let replay = service
            .ingest_receive(same_value, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            replay.is_empty(),
            "a replayed timer envelope dedupes through the row identity"
        );
    }

    /// The §4.75 attribution ladder: the editor ACI resolves through the
    /// recorded ACI→peer-key mapping first (the §4.37 identity table) so the
    /// row's sender face joins the desktop roster by its number form; an
    /// unmapped ACI rides raw (the desktop roster joins it by uuid); a
    /// stamp-less envelope keeps the mirror and lands no row (the row identity
    /// has no locally inventable half).
    #[test]
    fn ingest_group_timer_update_attributes_the_editor() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let aci = "11111111-2222-4333-8444-555555555555";
        service
            .store_ref()
            .upsert_peer_identity(&account.id, aci, "+15555550101")
            .unwrap();

        let receive = |editor: Option<&str>, timestamp: u64| NormalizedReceive {
            timestamp: Some(timestamp),
            content_kind: "control",
            direction: "control",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            server_timestamp: None,
            peer_name: None,
            group_id: Some("group-id-1".into()),
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::GroupTimerUpdate {
                expire_timer_seconds: 60,
                editor: editor.map(str::to_string),
            }),
        };

        // The recorded mapping resolves the editor to its number-keyed peer.
        let events = service
            .ingest_receive(
                receive(Some(aci), 1727000000000),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record.clone()),
                _ => None,
            })
            .expect("the attributed envelope lands its row");
        assert_eq!(upserted.conversation_id, conversation.id);
        assert_eq!(upserted.sender_id, "+15555550101");

        // An unmapped ACI rides raw — the desktop roster joins it by uuid.
        let events = service
            .ingest_receive(
                receive(Some("99999999-8888-4333-8444-555555555555"), 1727000001000),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record.clone()),
                _ => None,
            })
            .expect("the raw-ACI envelope lands its row");
        assert_eq!(upserted.sender_id, "99999999-8888-4333-8444-555555555555");

        // A stamp-less envelope keeps the mirror and lands no row.
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: None,
                    ..receive(Some(aci), 0)
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, HostSideEvent::MessageUpserted(_))),
            "a stamp-less envelope has no row identity to land"
        );
        assert!(
            events
                .iter()
                .any(|event| matches!(event, HostSideEvent::ConversationChanged(_))),
            "the mirror still converges"
        );
    }

    /// Contract 1.140 (§4.136): the blocked sync consumes into the §4.131
    /// blocked factor store — presence stamps true on every direct row the
    /// identity ladder resolves, the refreshed summaries ride
    /// `conversation.changed`, a replay is silent (the bit already reads
    /// true), an identity nothing resolves drops warn-only without
    /// inventing a conversation, the group half consumes nothing, and no
    /// message row is ever created.
    #[test]
    fn ingest_sync_blocked_stamps_the_factor_and_rides_conversation_changed() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let by_number = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        // A second row of the same subject keyed by the raw ACI (the sync
        // family's own key form): both forms must converge.
        let aci = "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10";
        let by_aci = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", aci, "8fc***e2")
            .unwrap();
        let before_number = service
            .store_ref()
            .conversation_summary(&account.id, &by_number.id)
            .unwrap()
            .unwrap();
        assert!(!before_number.blocked);

        let base = NormalizedReceive {
            control: Some(ControlReceive::SyncBlocked {
                blocked: crate::engine::SyncBlocked {
                    numbers: vec!["+15555550101".into()],
                    acis: vec![aci.to_string()],
                    group_ids: vec!["AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=".into()],
                },
            }),
            ..base_shape_for_unknown_test()
        };
        let events = service
            .ingest_receive(base.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, HostSideEvent::MessageUpserted(_))),
            "a block mirror is not a message row"
        );
        let changed: Vec<String> = events
            .iter()
            .filter_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary.id.clone()),
                _ => None,
            })
            .collect();
        assert_eq!(changed.len(), 2, "{changed:?}");
        assert!(changed.contains(&by_number.id) && changed.contains(&by_aci.id));
        for conversation_id in [&by_number.id, &by_aci.id] {
            let after = service
                .store_ref()
                .conversation_summary(&account.id, conversation_id)
                .unwrap()
                .unwrap();
            assert!(after.blocked, "the factor stamp must read true");
        }

        // The replay: both bits already read true — nothing stamps, nothing
        // emits.
        let events = service
            .ingest_receive(base, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(events.is_empty(), "{events:?}");

        // An identity nothing resolves drops warn-only (no conversation is
        // invented); the group-only half consumes nothing.
        let unknown = NormalizedReceive {
            control: Some(ControlReceive::SyncBlocked {
                blocked: crate::engine::SyncBlocked {
                    numbers: Vec::new(),
                    acis: vec!["99999999-9999-9999-9999-999999999999".into()],
                    group_ids: Vec::new(),
                },
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(unknown, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty()
        );
        let group_only = NormalizedReceive {
            control: Some(ControlReceive::SyncBlocked {
                blocked: crate::engine::SyncBlocked {
                    numbers: Vec::new(),
                    acis: Vec::new(),
                    group_ids: vec!["AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=".into()],
                },
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(group_only, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty(),
            "the group half rides the pull authority, nothing stamps"
        );
    }

    /// A groupUpdated naming a group nothing local resolves is warn-only
    /// dropped — better to converge late than to invent a row (宁缺勿错). The
    /// resolvable twin of this drop path is the mirror test above.
    #[test]
    fn ingest_group_timer_update_for_an_unknown_group_drops() {
        let (_temp, mut service) = service();
        service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    timestamp: Some(1727000000000),
                    content_kind: "control",
                    direction: "control",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: None,
                    source_uuid: None,
                    server_guid: None,
                    server_timestamp: None,
                    peer_name: None,
                    group_id: Some("dW5rbm93bi1ncm91cA==".into()),
                    text: None,
                    text_bytes: None,
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: Some(ControlReceive::GroupTimerUpdate {
                        expire_timer_seconds: 3600,
                        editor: None,
                    }),
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        assert!(events.is_empty(), "an unknown group converges nothing");
    }

    /// Contract 1.70 (§4.58 consume batch): the message-request response sync
    /// consumption. An ACCEPT mirror stamps the authoritative factor on the
    /// resolved direct conversation (the ACI ladder: raw ACI → the recorded
    /// ACI→peer-key mapping) and rides `conversation.changed` with the
    /// accepted state; a non-ACCEPT member (DELETE) stamps the terminal
    /// not-accepted; a mirror naming nothing local converges nothing; a
    /// group-threaded mirror is refused (groups carry no request); no message
    /// row is ever created.
    #[test]
    fn ingest_message_request_response_stamps_the_authoritative_factor() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-in");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();
        let base = NormalizedReceive {
            timestamp: Some(1727000000000),
            content_kind: "control",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            server_timestamp: None,
            peer_name: None,
            group_id: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
            }),
        };

        // Before the mirror: the incoming-only row is pending (the honest
        // no-stamp derivation). The mirror keys its thread by the peer's ACI,
        // so the §4.37 mapping that resolution walks is recorded up front —
        // the same shape a real receive chain leaves behind.
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        let before = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(!before.message_request_accepted);

        // The ACCEPT mirror flips it through conversation.changed and the
        // store state both.
        let events = service
            .ingest_receive(base.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, HostSideEvent::MessageUpserted(_))),
            "a response mirror is not a message row"
        );
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the stamp rides conversation.changed");
        assert_eq!(changed.id, direct.id);
        assert!(changed.message_request_accepted);
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.message_request_accepted);

        // The DELETE twin (member 2) stamps the terminal not-accepted back.
        let delete = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 2,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
            }),
            ..base.clone()
        };
        let events = service
            .ingest_receive(delete, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the delete stamp rides conversation.changed too");
        assert!(!changed.message_request_accepted);

        // The idempotent re-stamp: a same-value ACCEPT re-pushes the summary
        // (the GroupTimerUpdate convergence discipline).
        assert!(
            service
                .ingest_receive(base, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .iter()
                .any(|event| matches!(event, HostSideEvent::ConversationChanged(_)))
        );
        let stamped = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(stamped.message_request_accepted);

        // Nothing local (an unknown ACI) converges nothing.
        let unknown = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: Some("99999999-9999-9999-9999-999999999999".into()),
                group_id: None,
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(unknown, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty()
        );

        // A group-threaded mirror is refused: the request family is 1:1 only.
        let group_mirror = NormalizedReceive {
            group_id: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: None,
                group_id: Some("AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=".into()),
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(group_mirror, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty(),
            "groups carry no request to accept"
        );
    }

    /// Contract 1.138 (§4.131): the BLOCK family verbs (3/4/6) stamp the
    /// conversation's blocked bit through the same consume batch — the
    /// refreshed summary rides conversation.changed with blocked true, the
    /// terminal not-accepted answer stays, and a non-BLOCK verb never
    /// touches the mask.
    #[test]
    fn ingest_message_request_response_block_family_stamps_blocked() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        // The seeded incoming row pins the window answer to pending (an
        // empty private conversation derives accepted, the official
        // empty-private-conversation weight) — the same material the 1.70
        // test reads.
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-block");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();

        let block = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 3,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
            }),
            ..base_shape_for_unknown_test()
        };
        let events = service
            .ingest_receive(block, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the block stamp rides conversation.changed");
        assert!(changed.blocked);
        assert!(!changed.message_request_accepted);
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.blocked);

        // DELETE (2) closes the request without touching the mask.
        let delete = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 2,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
            }),
            ..base_shape_for_unknown_test()
        };
        service
            .ingest_receive(delete, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.blocked, "a non-BLOCK verb never rewrites the mask");
    }

    /// Contract 1.138 (§4.130): the local draft write lane — bounds, the
    /// unknown-account/unknown-conversation refusals, and the refreshed
    /// summary the caller rides conversation.changed with.
    #[test]
    fn store_draft_faces_bound_resolve_and_stamp() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let store = service.store_ref();

        // Bounds: empty id, oversize id, zero stamp, unknown account.
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, "", 5),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, &"x".repeat(257), 5),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, &direct.id, 0),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, "no-such-account", &direct.id, 5),
            Err(ServiceError::Store(StoreError::AccountNotFound))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, "no-such-conversation", 5),
            Err(ServiceError::Store(StoreError::ConversationNotFound))
        ));

        // The stamp lands and the summary carries it; the clear refreshes.
        let summary = store_save_conversation_draft(store, &account.id, &direct.id, 42).unwrap();
        assert_eq!(summary.draft_timestamp, Some(42));
        let summary = store_clear_conversation_draft(store, &account.id, &direct.id).unwrap();
        assert_eq!(summary.draft_timestamp, None);
    }

